(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["video"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-fp8-sparse-attn-video"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-1\">一 · 一次线上事故：当“统一低精度”把长镜头烧出白斑</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-2\">二 · 算法要解决的具体推理问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-3\">三 · 适用边界：长帧、平缓占比高，才配得上这套机制</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-4\">四 · 代价落在哪里：gather破坏访存连续性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-5\">五 · 失败案例的复盘：三个必须前置拦截的点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-6\">六 · 失效边界：稀疏率、访存局部性与镜头切换</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-7\">七 · 入口：latent 下采样与 draft 注意力的输入输出</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-8\">八 · 分档：阈值规则与索引/标签的生成代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-9\">九 · 主注意力：gather QKV 与两条 MMA 路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-10\">十 · 填充：skip 块的邻帧外推与 KV 写回</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-11\">十一 · 校正：VAE 解码前的 BF16 残差</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-12\">十二 · 流水重叠与净收益的判定条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-13\">十三 · 分档阈值与稀疏索引的工程边界：从draft分数到gather代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-14\">十四 · 主公式的逐项拆解：两条求和路径在算什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-15\">十五 · 分档规则的推导：阈值从哪来、为什么是两级</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-16\">十六 · draft 估计的可实现形式：下采样 2× 与分数生成</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-17\">十七 · 主注意力的 gather 与流水：索引如何喂给 WGMMA</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-18\">十八 · 填充与外推的误差传播：skip 块为什么不能置零</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-19\">十九 · 公式到部署配方的映射：三个可调旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-20\">二十 · 请求形态：什么样的负载才配得上这套配方</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-21\">二十一 · 长度分布：阈值切分依赖分布的“双峰性”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-22\">二十二 · 并发与批大小：被KV分档存储和索引显存卡住</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-23\">二十三 · 负载不对时：三种可观测的退化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-24\">二十四 · 配方参数与SLO的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-25\">二十五 · 负载配方：长帧平缓视频才是它的主场</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-26\">二十六 · 硬件档位与并行拓扑的绑定关系</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-27\">二十七 · 量化方案的档位配比与累加策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-28\">二十八 · KV 策略：按精度标签分档存储与 gather 布局</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-29\">二十九 · 调度参数：批间重排窗口与稀疏开关</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-30\">三十 · 可复现的配置思路：从档位到参数的落地顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-31\">三十一 · 三档精度配方的边界：从稀疏率与访存连续性反推部署档位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-32\">三十二 · 显存账：三档标签把KV从连续数组变成三张表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-33\">三十三 · 带宽账：gather 把算力节省换成随机读取代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-34\">三十四 · 通信与多流：draft 开销只能靠重叠隐藏，不能靠削减</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-35\">三十五 · 功耗与占用：稀疏不等于省电，空转的 SM 照样耗电</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-36\">三十六 · 尾延迟：镜头切换处的外推填充是长尾来源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-37\">三十七 · 规模上去以后哪里先崩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-38\">三十八 · 稀疏率决定盈亏平衡点，而非算力峰值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-39\">三十九 · 先崩的是HBM随机访存，不是Tensor Core</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-40\">四十 · 精度分档的隐性代价在写回与校正</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-41\">四十一 · 精度分档失效：从“过曝”到“欠采样”的两种反向错误</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-42\">四十二 · OOM：稀疏索引与KV分档存储的显存账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-43\">四十三 · 批抖动与路由不均：连续批处理下的稀疏率方差</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-44\">四十四 · 尾延迟尖刺：gather访存与draft未隐藏</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-45\">四十五 · 外推污染与回滚：skip块错误传播的止损</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-46\">四十六 · 失效边界：从分档阈值到回滚判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-47\">四十七 · 同族算法的三条分界线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-48\">四十八 · 决策表：按场景与约束选型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-49\">四十九 · 与FP8稠密内核的对照：阈值怎么定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-50\">五十 · 与动态稀疏时空注意力的对照：精度维度是否必要</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-51\">五十一 · 与KV量化、缓存复用条目的对照：瓶颈定位决定选型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-52\">五十二 · 适用条件的硬边界与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-sparse-attn-video-sec-53\">五十三 · 选型边界：什么时候该用精度分配稀疏注意力，什么时候不该</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:534px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 534.1 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"452.1\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">输入latent先下采样2×做一次轻量draft注意力，得到每帧每头的块级…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"452.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按阈值把时空块分为skip/FP4/FP8三档，生成稀疏索引与精度标签。</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"452.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">主注意力按索引 gather QKV，FP8档走FlashAttentio…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"452.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">对skip块用邻帧注意力输出做线性外推填充，写回KV cache。</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"452.1\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">VAE解码前对低精度块做一次BF16残差校正，抑制条带伪影。</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-fp8-sparse-attn-video-sec-1\">一 · 一次线上事故：当“统一低精度”把长镜头烧出白斑</h3>\n<p>某条视频生成服务在Blackwell集群上把DiT的3D全注意力整体切到FP4，压测时指标漂亮：注意力算力下降、KV读取变窄、单步时延缩短。上线后第一批投诉来自风景类长镜头——天空、水面、大面积墙面出现成片过曝白斑，边缘还带条带。回滚到BF16后白斑消失，但时延回到不可接受的水平。事故报告里两个现象并列出现：平滑区域在低精度下softmax分布被压平，权重集中到少数块上导致输出幅值溢出；而高频运动区域（快速摇镜、人群走动）在低精度下采样不足，细节被抹成糊块。同一个全局精度档位，在两个方向上同时失败。</p>\n<p>这不是精度选得不够高的问题，而是“一个档位服务所有内容”的结构性错误。视频DiT的注意力图在时空上极不均匀：一段十秒长镜头里，可能八成的时空块是缓慢漂移的背景，两成是剧烈运动的局部。对前者，注意力权重接近均匀、数值动态范围小，FP4的尾数足以表达；对后者，权重尖峰、需要FP8的动态范围才能保住排序。把两者塞进同一个精度档，要么平滑区过曝，要么运动区欠采样。事故的真正代价不是那批废片，而是团队被迫在“全局FP8的时延”和“全局FP4的质量”之间二选一，而这两个选项都不满足SLO。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-2\">二 · 算法要解决的具体推理问题</h3>\n<p>该算法针对的推理问题是明确的：视频DiT的3D全注意力在长帧序列上呈O(N^2)复杂度，N同时包含帧数与每帧token数，长帧序列直接把注意力时延与KV带宽推到主导地位；同时，统一低精度量化会在内容维度上产生方向相反的两类失真。算法要做的，是按内容动态分配注意力的精度与稀疏度，让平滑块走FP4甚至直接跳过，让高频块走FP8稠密，从而在Blackwell上同时省下带宽与算力。</p>\n<p>形式化地，注意力输出被拆成两段求和：</p>\n<div class=\"formula\">$$\\text{Attn}(Q,K,V)=\\sum_{b\\in\\mathcal{S}_{\\text{FP8}}}\\mathrm{softmax}(Q_bK_b^{\\top}/\\sqrt{d})V_b+\\sum_{b\\in\\mathcal{S}_{\\text{FP4}}}\\hat{A}_bV_b,\\quad \\text{FLOPs}\\approx \\rho_{\\text{FP8}}N^2d+\\rho_{\\text{FP4}}\\tfrac{N^2d}{2}$$</div>\n<p>其中$\\mathcal{S}_{\\text{FP8}}$与$\\mathcal{S}_{\\text{FP4}}$是由内容决定的时空块划分，$\\hat{A}_b$是低精度路径下的近似注意力权重，$\\rho$为两条路径的算力占比。关键在于两个集合不是静态的：它们随去噪步、随latent内容变化。分档规则由draft阶段给出的块级重要性分数$s$决定：</p>\n<div class=\"formula\">$$\\text{tier}=\\begin{cases}\\text{skip}, &amp; s&lt;\\tau_1\\\\ \\text{FP4}, &amp; \\tau_1\\le s&lt;\\tau_2\\\\ \\text{FP8}, &amp; s\\ge\\tau_2\\end{cases}$$</div>\n<p>这套划分解决的是“精度与稀疏度必须随内容走”的问题。它不解决的是：权重与激活的静态4bit量化（那是NVFP4分块量化推理的职责，作用于FFN与投影，与本算法作用在时空注意力上互补而非重叠）；也不解决少步蒸馏带来的采样步数压缩、VAE解码的分块重叠、轨迹感知的跨步缓存复用。换句话说，它只动注意力这一层的算力与带宽账本，其他环节的账本各自有别的条目负责。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-3\">三 · 适用边界：长帧、平缓占比高，才配得上这套机制</h3>\n<p>算法的收益结构由稀疏率决定。draft注意力本身有开销——即便下采样2×做轻量估计，它仍是一次真实的注意力计算，需要读取latent、写出块级分数。当主注意力因稀疏跳过而省下的FLOPs与KV读取大于draft开销时，净收益为正；当视频短、动态高、稀疏率低时，skip与FP4档占比小，主注意力省不下多少，draft开销却照付，净收益可能为负，每步时延反而增加。因此适用边界写得很窄：长帧序列、运动平缓占比高的视频去噪请求。</p>\n<p>工程上这意味着不能默认开启。服务侧需要一条按内容判定的开关：先用极低成本的内容统计（帧间latent差分、运动能量直方图）估计潜在稀疏率，低于阈值就走稠密FP8路径，不进入draft分档流程。批大小也受约束——KV cache按精度标签分档存储以配合gather，稀疏索引本身占显存，二者共同压低可并发请求数。SLO以每步注意力时延为主指标，而不是端到端吞吐，因为该算法优化的是单步内的注意力账本。</p>\n<table class=\"mini\"><thead><tr><th>场景</th><th>稀疏率</th><th>净收益判断</th><th>工程动作</th></tr></thead><tbody><tr><td>长镜头、慢摇、大面积平滑背景</td><td>高</td><td>正，FLOPs与KV读取双降</td><td>启用draft分档与skip外推</td></tr><tr><td>短片段、高动态、快速剪辑</td><td>低</td><td>可能为负，draft开销无法摊薄</td><td>绕过稀疏路径，走稠密FP8</td></tr><tr><td>镜头切换密集的叙事视频</td><td>中</td><td>需评估外推错误传播</td><td>切换帧强制FP8，禁用skip外推</td></tr></tbody></table>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-4\">四 · 代价落在哪里：gather破坏访存连续性</h3>\n<p>最容易被低估的代价不是算力，而是访存。主注意力按稀疏索引gather QKV，索引把原本连续的时空块打散，HBM上变成随机读取。Blackwell的WGMMA异步流水擅长的是连续、可预取的张量块；一旦gather把块布局打乱，预取失效，HBM随机读取代价会抵消算力节省，注意力时延不降反升。这是该算法最典型的失败模式，且它不报错——指标上FLOPs确实降了，时延却变差，排查方向容易被误导到别处。</p>\n<p>对应的工程判断是：块布局必须预排布。在draft阶段产出分档结果后，先按tier重排时空块在显存中的物理顺序，把同档块聚成连续段，再让主注意力按段读取而非按散点gather。这样FP8档与FP4档各自成为连续区间，WGMMA流水得以恢复。代价是重排本身要写一次索引映射表，且KV cache需按精度标签分档存储，显存开销上升。是否值得，取决于稀疏率能否覆盖重排与draft的固定成本。</p>\n<p>另一条代价线是draft与主注意力的重叠。draft开销要被隐藏，必须放在Blackwell的多流上与主注意力异步重叠：draft算第$t+1$步的块级分数时，主注意力正在算第$t$步。若重叠失败——比如draft与主注意力争抢同一份KV带宽——draft开销就裸露在关键路径上，短视频场景下直接表现为每步时延增加。这也是为什么该算法把“多流异步WGMMA重叠”写进部署配方，而不是当作可选优化。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-5\">五 · 失败案例的复盘：三个必须前置拦截的点</h3>\n<p>回到开头的事故，它其实踩中了三条失败路径中的第一条的变体。第一条：gather未预排布，HBM随机读取吃掉算力收益，时延不降反升。第二条：draft开销未被多流重叠隐藏，短视频或高动态场景稀疏率低，净收益为负且额外增加每步时延。第三条最隐蔽：skip块用邻帧注意力输出做线性外推填充而非置零，这在镜头切换处会出错——邻帧内容与当前帧无关，外推出来的值写回KV cache后污染后续帧的注意力输出，错误沿时间轴传播，表现为切换后若干帧的鬼影。</p>\n<p>三条路径的共同点是：它们都不在“算力账本”上体现，而在访存、流水、缓存一致性上体现。因此上线前的拦截点应放在这三处，而不是盯着FLOPs下降比例。具体做法：对gather路径做块布局预排布的强制校验，未排布的索引直接拒绝进入主注意力；对draft开销做多流重叠的时延埋点，重叠率低于阈值时自动降级到稠密路径；对镜头切换做检测，切换帧强制FP8稠密并禁用skip外推，避免污染KV cache。VAE解码前的BF16残差校正只能抑制条带伪影，救不了外推错误传播——那是写回时机的问题，不是精度问题。</p>\n<p>这套算法的工程判断可以压缩成一句：它是一把按内容开刃的刀，刃口在稀疏率上。长帧、平缓、稀疏率高的请求，它同时省带宽和算力；短、快、切换密的请求，它把draft与gather的固定成本摊不开，净收益为负。服务侧必须有能力在请求进入注意力之前判定走哪条路，而不是让算法自己在关键路径上试错。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-6\">六 · 失效边界：稀疏率、访存局部性与镜头切换</h3>\n<p>这套精度分配稀疏时空注意力真正要解决的，是视频 DiT 里 3D 全注意力在长帧序列上的 O(N²) 爆炸，以及“一刀切低精度”带来的双向失真：平滑区域被 FP4 量化到过曝，高频运动区域又因统一稀疏而欠采样。它把注意力拆成两段——<span class=\"formula\">$$\\text{Attn}(Q,K,V)=\\sum_{b\\in\\mathcal{S}_{\\text{FP8}}}\\mathrm{softmax}(Q_bK_b^{\\top}/\\sqrt{d})V_b+\\sum_{b\\in\\mathcal{S}_{\\text{FP4}}}\\hat{A}_bV_b,\\quad \\text{FLOPs}\\approx \\rho_{\\text{FP8}}N^2d+\\rho_{\\text{FP4}}\\tfrac{N^2d}{2}$$</span>——用低分辨率 latent 的 draft 注意力图给每个时空块打分，再按 <span class=\"formula\">$$\\text{tier}=\\begin{cases}\\text{skip}, &amp; s&lt;\\tau_1\\\\ \\text{FP4}, &amp; \\tau_1\\le s&lt;\\tau_2\\\\ \\text{FP8}, &amp; s\\ge\\tau_2\\end{cases}$$</span> 分档。注意这里的 FLOPs 只是算力账，真正的系统代价还要加上 gather 带来的 HBM 随机读取，后者往往才是线上事故的元凶。</p>\n<p>一个典型的线上失败案例：某长帧去噪服务上线后，注意力时延不降反升，SLO 直接击穿。根因不在精度分档，而在稀疏索引 gather——时空块被跳过后索引变得不连续，主注意力按索引取 QKV 时打散了原本连续的块布局，HBM 随机读取代价抵消了算力节省，甚至倒挂。这类失效的判据很直接：只有当 <span class=\"formula\">$$\\text{节省算力} &gt; \\text{draft 开销} + \\text{gather 额外带宽}$$</span> 时净收益才为正。工程上必须预排布块布局，让同一精度档的块在显存中物理相邻，否则 FP4 档省下的那部分 MMA 时间会被访存完全吃掉。这也解释了为什么该算法在短视频、高动态场景下稀疏率低时净收益可能为负——可跳过的块太少，draft 与索引管理的固定成本无处摊薄。</p>\n<p>它明确不解决的问题同样要划清。第一，它作用于时空注意力，不碰 FFN 与投影的静态权重量化——那是 NVFP4 分块量化推理的职责，两者是不同层面的省法，不能互相替代。第二，它不解决批调度与 KV 容量规划：批大小受 KV cache 与稀疏索引显存双重约束，KV 需按精度标签分档存储以配合 gather，这本身是一笔显存开销，长帧高分辨率请求下索引元数据会挤占本已紧张的 KV 空间。第三，skip 块用邻帧注意力输出线性外推填充并写回 KV cache，在镜头切换处会错误传播——外推假设时间连续性，切镜瞬间邻帧语义断裂，污染后的 KV 会持续影响后续帧，这是内容层面的失效，靠调阈值救不回来。</p>\n<p>适用边界的工程判断可以压成一张表：长帧序列、运动平缓占比高、镜头稳定，是它的主场；短视频、高动态、频繁切镜，应默认关闭稀疏路径或仅启用精度分档而不 skip。部署上它面向 Blackwell 档位，靠多流异步 WGMMA 把 draft 与主注意力重叠以隐藏 draft 开销——一旦重叠没做起来，draft 的固定成本就直接暴露在每步时延里。规模上限由 draft 开销占比与稀疏率共同约束，而不是由 GPU 峰值算力决定；换句话说，这是一套“按内容赌稀疏率”的方案，赌赢的前提是块布局预排布到位、镜头边界有检测兜底。</p>\n<h3 id=\"alg-fp8-sparse-attn-video-sec-7\">七 · 入口：latent 下采样与 draft 注意力的输入输出</h3>\n<p>整条流水线的第一步发生在主注意力之前：拿到当前去噪步的 latent 张量，形状按 <em>[帧数 F × 空间 token 数 H·W × 通道 C]</em> 组织，先做 2× 空间下采样，再在降采样后的序列上跑一次轻量 draft 注意力。输入是完整 latent 与当前步的 QKV 投影权重；输出不是注意力结果本身，而是每帧、每头、每个时空块的重要性分数 <em>s</em>。draft 的序列长度约为原序列的 1/4（空间 2× 下采样在两个维度上各减半），因此其注意力 FLOPs 相对主注意力约为 <em>(N/4)²/N² = 1/16</em> 量级——这个比例决定了 draft 开销能否被后续节省覆盖。</p>\n<p>代价落在两处。其一是算力：draft 仍是一次真实的 QK^T 与 softmax·V，即便序列短，头数不变，在 Blackwell 上表现为一段额外的 WGMMA 工作量。其二是显存带宽：下采样需要一次读 latent、一次写降采样副本，若降采样副本不常驻，则每步都重复这笔读写。工程上把降采样结果按去噪步缓存、只在 latent 变化超过阈值时重算，是把这一步从“每步固定税”变成“条件税”的常见做法。具体例子：一段 32 帧、每帧 64×64 latent token 的序列，主注意力 N≈13 万，draft 序列 N≈3.3 万，draft 单步时延由 QK^T 的 MMA 迭代次数与 softmax 归约主导，而非由 HBM 读取主导——这正是它能在多流上与主注意力重叠的前提。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-8\">八 · 分档：阈值规则与索引/标签的生成代价</h3>\n<p>draft 分数出来后进入分档。规则是硬阈值三段式：</p>\n<div class=\"formula\">$$\\text{tier}=\\begin{cases}\\text{skip}, &amp; s&lt;\\tau_1\\\\ \\text{FP4}, &amp; \\tau_1\\le s&lt;\\tau_2\\\\ \\text{FP8}, &amp; s\\ge\\tau_2\\end{cases}$$</div>\n<p>输入是每帧每头的块级分数 <em>s</em>，输出是两张表：稀疏索引（哪些块进入主注意力、按什么顺序 gather）与精度标签（每个块走 FP8 稠密还是 FP4 低精度 MMA）。这一步几乎不耗算力，但耗的是“布局决策”的时延：索引必须按主注意力内核期望的块排布写出，否则后续 gather 就是随机读。阈值 <em>τ₁、τ₂</em> 不是全局常数——按头、按帧分别标定更稳，因为不同注意力头对运动的敏感度差异很大，全局单阈值会把某些头的平滑块误判为高频、把另一些头的高频块误判为平滑。</p>\n<p>系统代价体现在索引显存的占用上：索引与标签随批大小线性增长，而批大小本身受 KV cache 与稀疏索引显存双重约束。一个具体判断是：当批内序列长度差异大时，按最长序列预留索引空间会浪费显存，按块粒度压缩存储（每块一个 tier 字节 + 偏移）比按 token 存布尔掩码更省。这一步的输出质量直接决定后面两步的收益上限——分档错了，FP8 档白算、skip 档白跳。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-9\">九 · 主注意力：gather QKV 与两条 MMA 路径</h3>\n<p>主注意力按索引 gather QKV。FP8 档走 FlashAttention-3 风格的异步 WGMMA：QK^T 在 FP8 下做 MMA、softmax 在 FP32 域归约、PV 再回 FP8，整条链靠异步流水把 MMA 与 softmax 的重叠做满。FP4 档走低精度 MMA 但保留 FP32 累加器，这是不让低精度块在累加中丢动态范围的关键——FP4 的尾数极窄，若累加也用低精度，平滑块的缓慢变化会被量化噪声吞掉。两档混合后的 FLOPs 近似为：</p>\n<div class=\"formula\">$$\\text{FLOPs}\\approx \\rho_{\\text{FP8}}N^2d+\\rho_{\\text{FP4}}\\tfrac{N^2d}{2}$$</div>\n<p>其中 <em>ρ</em> 是各档覆盖的块比例。注意 FP4 项的系数 1/2 来自低精度 MMA 的吞吐倍率，而非精度本身。代价的核心不在算力而在访存：gather 把原本连续的 KV 读取打散成按块索引的跳跃访问，若块布局未预排布成与索引同序的连续段，HBM 随机读取代价会吃掉算力节省，注意力时延不降反升。工程上的解法是在分档步骤就把 KV 按 tier 重排成三段连续区（skip 段不读、FP4 段、FP8 段），主注意力按段顺序发射，把 gather 退化为“按段基址 + 段内偏移”的规则访问。</p>\n<p>具体例子：一个头内 80% 块落入 skip、15% 落 FP4、5% 落 FP8 时，KV 读取量降到原来的约 20%，但若这 20% 分散在 64 个不连续段里，每段不足一个 128B 缓存行，有效带宽利用率会跌到连续访问的几分之一。这正是“预排布块布局”不是优化项而是前置条件的理由。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-10\">十 · 填充：skip 块的邻帧外推与 KV 写回</h3>\n<p>skip 块不计算，但不能留空。做法是用邻帧同位置的注意力输出做线性外推填充，再把填充结果写回 KV cache。输入是该块在相邻帧（前向或后向，取决于帧序与缓存策略）已算出的注意力输出，输出是当前帧该块的近似 KV 值。线性外推的假设是：被判定为平滑的时空块在相邻帧间变化近似线性，因此两点外推的误差由二阶差分控制。这一步的代价是纯访存：读邻帧 KV、写当前帧 KV，无 MMA。它把“跳过计算”换成了“搬运数据”，在带宽富余而算力紧张的 Blackwell 上是划算的，但在 KV cache 已接近容量上限、写回触发换出时就不划算。</p>\n<p>失败模式很明确：镜头切换处邻帧外推失效，错误值写回 KV cache 后会污染后续帧的注意力输出，且污染随去噪步累积。工程判断是给外推加一个门控——邻帧间 latent 差异超过阈值时，该块强制降级为 FP4 实算而非外推，用一点算力换掉错误传播。这一步也解释了为什么 skip 档不能简单地“置零”：置零在注意力输出上产生空洞，softmax 归一化后会把空洞放大成可见伪影。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-11\">十一 · 校正：VAE 解码前的 BF16 残差</h3>\n<p>低精度块在 VAE 解码前做一次 BF16 残差校正。输入是 FP4/FP8 档算出的注意力输出与同块在 BF16 下的一阶近似（通常用该块 draft 阶段保留的低分辨率统计量重建），输出是校正后的残差加到原输出上。这一步针对的是条带伪影：FP4 的块级量化在平滑渐变区域会产生阶梯状误差，VAE 的上采样会把阶梯放大成可见条带。校正只作用于被标记为低精度的块，因此其代价与低精度块比例成正比，而非与全序列成正比。</p>\n<p>代价上，这是一次额外的 BF16 读写与逐元素加，在 VAE 解码前的整条链里占比不大，但它把“精度分配”的收益锁住——没有这一步，FP4 档的省算力会被解码端的画质回退抵消。具体例子：一段以静态背景为主的长镜头，skip 与 FP4 档占比高，若不做残差校正，背景渐变区在解码后出现横向条带；校正后条带被压到量化噪声水平以下。这一步也意味着精度标签必须一路传到 VAE 前，标签的生命周期比注意力本身更长。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-12\">十二 · 流水重叠与净收益的判定条件</h3>\n<p>把五步串起来看，真正的工程问题不是单步代价而是重叠结构。draft 与主注意力在 Blackwell 多流上异步重叠：draft 在第 <em>k</em> 步的分数生成与第 <em>k−1</em> 步的主注意力 WGMMA 并行发射，用主注意力的 MMA 占用掩盖 draft 的算力开销。分档与索引生成是纯标量/访存工作，可放在第三条流上，与两者都不争 MMA。填充与校正则在主注意力之后、VAE 之前，属于串行段，无法被重叠隐藏。</p>\n<p>净收益的判定可以写成一个粗略的不等式：设 draft 开销为 <em>C_d</em>、主注意力原代价为 <em>C_a</em>、稀疏与精度分配后的主注意力代价为 <em>C_a'</em>、填充与校正的访存代价为 <em>C_f</em>，则启用稀疏路径的条件是 <em>C_a − C_a' &gt; C_d + C_f</em>，且 <em>C_d</em> 中未被重叠隐藏的部分才真正计入。这解释了为什么短视频或高动态场景稀疏率低时净收益为负：<em>C_a − C_a'</em> 随稀疏率下降而收缩，而 <em>C_d</em> 与 <em>C_f</em> 不随内容收缩。工程判断是按内容动态决定是否启用稀疏路径——先跑 draft，若全局平均分数高于阈值（说明高频块占比大、稀疏率低），直接回退到全 FP8 稠密路径，把 draft 的开销当作一次廉价的探测成本，而不是无条件走完五步。</p>\n<p>规模上限由此被两个量约束：draft 开销占主注意力的比例，以及可达稀疏率。前者由下采样倍率与头数决定，后者由视频内容决定。二者共同决定了这条流水线在长帧、运动平缓占比高的视频上是正收益，而在高动态短序列上应当关闭。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-13\">十三 · 分档阈值与稀疏索引的工程边界：从draft分数到gather代价</h3>\n\n<p>把机制落到数据流上，每一步的代价并不对称。第一步draft注意力在2×下采样latent上做，输入是降采样后的Q/K/V，输出是每帧每头的块级重要性分数$s$；其FLOPs约为主注意力的四分之一量级（序列长度减半、头数不变），但它是串行前置，若不被多流重叠隐藏，就直接叠加进每步时延。第二步分档本身几乎零算力，代价在元数据：按$\\text{tier}=\\text{skip}(s&lt;\\tau_1),\\ \\text{FP4}(\\tau_1\\le s&lt;\\tau_2),\\ \\text{FP8}(s\\ge\\tau_2)$生成稀疏索引与精度标签，需要为每个时空块记录偏移、档位与目标KV分档地址，这部分显存随块数线性增长，并与KV cache争抢容量，直接压低可承载的批大小。第三步gather QKV是真正的分水岭：FP8档走FlashAttention-3风格异步WGMMA，FP4档走低精度MMA并保留FP32累加，算力按$\\text{FLOPs}\\approx\\rho_{\\text{FP8}}N^2d+\\rho_{\\text{FP4}}N^2d/2$下降，但只有索引连续时省下的算力才兑现为时延。</p>\n\n<p>失效条件集中在两处。其一是稀疏率：短视频或高动态场景中$s$普遍越过$\\tau_2$，skip与FP4档占比低，draft开销与索引维护成本无法被摊薄，净收益为负，此时应关闭稀疏路径走纯FP8稠密。其二是访存连续性：gather按块索引跳读，若块布局未按索引顺序预排布，HBM随机读取代价会抵消算力节省，注意力时延不降反升——这是最隐蔽的失败模式，因为FLOPs账面上是下降的。此外，skip块用邻帧注意力输出线性外推填充并写回KV cache，在镜头切换处会把错误外推值污染后续帧的注意力输出，属于跨帧传播型失效，阈值$\\tau_1$在切变检测信号上应临时抬高。</p>\n\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入→输出</th><th>主要代价</th><th>失效触发</th></tr></thead><tbody><tr><td>draft注意力</td><td>2×下采样latent→块级分数$s$</td><td>前置串行时延，需多流重叠</td><td>未被隐藏则净增每步时延</td></tr><tr><td>分档与索引</td><td>$s$→稀疏索引、精度标签</td><td>索引显存挤占KV cache，压批大小</td><td>块数多时批大小受限</td></tr><tr><td>gather主注意力</td><td>索引→FP8/FP4分档输出</td><td>随机HBM读取</td><td>未预排布块布局时时延反升</td></tr><tr><td>外推填充</td><td>邻帧输出→skip块KV</td><td>写回KV cache</td><td>镜头切换处错误传播</td></tr></tbody></table>\n\n<p>系统代价的账要按SLO算：该形态以每步注意力时延为主指标，批大小受KV cache与稀疏索引显存双重约束，因此索引元数据必须压缩（如按帧-头两级位图而非逐块指针），KV按精度标签分档存储以配合gather的连续性。工程判断是——启用稀疏路径的前提不是“视频长”，而是“平缓块占比高且块布局已预排布”，两者缺一，收益即转为负；BF16残差校正在VAE解码前只做一次，属于廉价保险，但不能修复gather引起的时延回退。</p>\n<h3 id=\"alg-fp8-sparse-attn-video-sec-14\">十四 · 主公式的逐项拆解：两条求和路径在算什么</h3>\n<p>核心公式写成两段求和，不是为了好看，而是为了把“精度分档”这件事直接编码进注意力算子的数学结构里：</p>\n<div class=\"formula\">$$\\text{Attn}(Q,K,V)=\\sum_{b\\in\\mathcal{S}_{\\text{FP8}}}\\mathrm{softmax}(Q_bK_b^{\\top}/\\sqrt{d})V_b+\\sum_{b\\in\\mathcal{S}_{\\text{FP4}}}\\hat{A}_bV_b,\\quad \\text{FLOPs}\\approx \\rho_{\\text{FP8}}N^2d+\\rho_{\\text{FP4}}\\tfrac{N^2d}{2}$$</div>\n<p>第一项是“保真项”。下标 $b$ 遍历被划入 FP8 档的时空块集合 $\\mathcal{S}_{\\text{FP8}}$，$Q_bK_b^{\\top}$ 是块内查询与键的点积，除以 $\\sqrt{d}$ 做温度归一化后过 softmax 得到真实的注意力权重矩阵，再右乘 $V_b$。注意这里没有做任何近似——softmax 在 FP8 张量上计算但累加走 FP32，因此这一项的输出与全精度稠密注意力在数值上是同一量级，区别只在输入被压到 FP8。它承担的是高频运动区域、边缘、镜头切换附近那些“权重分布尖锐、低精度会直接抹掉峰值”的块。</p>\n<p>第二项是“近似项”。$\\hat{A}_b$ 是 FP4 档块上的注意力权重估计，它不再由块内完整的 $Q_bK_b^{\\top}$ 现算，而是复用 draft 阶段已经得到的块级重要性分数经归一化后铺开成权重，或者用低秩近似重建。这一项乘以 $V_b$ 完成加权求和，累加仍是 FP32。关键在于 $\\hat{A}_b$ 的构造方式决定了误差上界：若直接拿 draft 的标量分数当均匀权重，块内空间结构丢失，平滑区域尚可，纹理区域会出现块状模糊；若用 draft 的低分辨率注意力图上采样，则保留了粗粒度结构，误差主要落在块内高频分量上，而这部分恰好由邻帧外推和 VAE 前的 BF16 残差校正兜底。</p>\n<p>FLOPs 估计式里 $\\rho_{\\text{FP8}}$ 与 $\\rho_{\\text{FP4}}$ 分别是两档块占全部时空块的比例，$\\rho_{\\text{FP8}}+\\rho_{\\text{FP4}}\\le 1$，差额即 skip 块。$N^2d$ 是稠密注意力的标准量级，FP4 档前的 $\\tfrac{1}{2}$ 来自低精度 MMA 在 Blackwell 上对相同逻辑运算的吞吐折算——它不是数学上的减半，而是硬件执行同一份 $N^2d$ 工作量所需的等效算力代价减半。把两项相加，就能读出这条公式的工程含义：总算力由两档比例线性加权，稀疏率越高、FP4 占比越大，省得越多，但第一项的系数 $\\rho_{\\text{FP8}}$ 是保真底线，不能压到零。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-15\">十五 · 分档规则的推导：阈值从哪来、为什么是两级</h3>\n<p>三档划分写成阶梯函数：</p>\n<div class=\"formula\">$$\\text{tier}=\\begin{cases}\\text{skip}, &amp; s&lt;\\tau_1\\\\ \\text{FP4}, &amp; \\tau_1\\le s&lt;\\tau_2\\\\ \\text{FP8}, &amp; s\\ge\\tau_2\\end{cases}$$</div>\n<p>其中 $s$ 是 draft 阶段得到的块级重要性分数。推导的关键一步在于把“精度分配”转化为“误差预算分配”：设块 $b$ 在 FP4 下的输出误差为 $\\epsilon_4(b)$、在 FP8 下为 $\\epsilon_8(b)$，且 $\\epsilon_4\\gg\\epsilon_8$；设该块对最终去噪结果的敏感度为 $s(b)$（即 draft 分数，衡量该块注意力权重对扰动的放大倍数）。则总误差近似为 $\\sum_b s(b)\\cdot\\epsilon_{\\text{tier}(b)}$，而总算力为 $\\sum_b c_{\\text{tier}(b)}$。这是一个带约束的分配问题：在总算力预算下最小化加权误差，其拉格朗日解天然给出按 $s/\\epsilon$ 比值排序的分档——高敏感度块必须给低误差档（FP8），低敏感度块给高误差档（FP4），敏感度低于噪声本底的块直接 skip。两级阈值 $\\tau_1,\\tau_2$ 就是这条排序曲线上的两个断点。</p>\n<p>为什么必须是两级而不是一级（稠密/跳过）？因为一级划分会在 $\\tau$ 附近产生硬切换：略高于阈值的块走全精度稠密，略低于的块直接置零，中间那段“值得算但不值得全精度算”的块没有归宿，表现为画面中沿阈值等值线出现的精度断层。插入 FP4 档相当于给误差预算加了一个中间台阶，让 $s$ 的连续分布映射到三档离散代价时，量化台阶变细。工程上 $\\tau_1$ 由 skip 块外推填充的可接受误差决定，$\\tau_2$ 由 FP4 在该块上的实测误差是否超过 VAE 残差校正的抑制能力决定——两者都不是拍脑袋常数，而是随内容统计量（帧间运动幅度、latent 方差）在线估计。</p>\n<p>代价侧要盯住一个反直觉点：分档本身几乎不花算力，但阈值判定需要每帧每头的分数排序，这在头数多、帧数长时是一次 $O(N_b\\log N_b)$ 的轻量操作，可忽略；真正昂贵的是分档结果落到显存后的索引结构——三档意味着 KV cache 要按精度标签分段存储，gather 时的地址跳变直接决定 HBM 随机读取代价。这就是为什么阈值不能取得过细：档位越多，索引越碎，访存惩罚越重。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-16\">十六 · draft 估计的可实现形式：下采样 2× 与分数生成</h3>\n<p>draft 注意力的伪代码落到可实现层面，核心是“在低分辨率 latent 上算一次便宜的全注意力，把结果映射回块级分数”：</p>\n<ul>\n<li>输入 latent $X\\in\\mathbb{R}^{F\\times H\\times W\\times C}$，先做 2× 空间下采样与帧抽样，得到 $X'\\in\\mathbb{R}^{F'\\times H/2\\times W/2\\times C}$，$F'$ 为抽样帧数。</li>\n<li>在 $X'$ 上跑一次标准多头注意力（可用 FP8 输入、FP32 累加），得到每帧每头的低分辨率注意力图 $A'\\in\\mathbb{R}^{F'\\times H'\\times W'}$。</li>\n<li>把 $A'$ 按块粒度（如 $p\\times p$ 的时空块）做池化，得到块级分数 $s_{f,h,b}$，再跨头取最大值或加权和，得到每帧每块的标量 $s$。</li>\n<li>对 $s$ 做跨帧归一化（除以该头该帧的分数均值），消除不同帧亮度/运动幅度带来的整体偏移，使 $\\tau_1,\\tau_2$ 可以全局共享。</li>\n</ul>\n<p>这里的关键设计是下采样倍率与块粒度的匹配：2× 下采样意味着 draft 的每个 token 对应主注意力的 4 个空间 token，块粒度若取 $2\\times2$ 则 draft 一个 token 恰好对应一个块，池化退化为直接取值，省掉一次 reduce；若块粒度更大，则池化窗口覆盖多个 draft token，分数更平滑但空间分辨率下降，容易把小块高频运动误判为平滑。伪代码层面应把块粒度作为编译期常量传入 kernel，让池化在寄存器内完成而不是走 shared memory 往返。</p>\n<p>draft 的代价必须被量化：它本身是一次 $O(N'^2d)$ 的注意力，$N'$ 约为 $N/4$（2× 空间下采样叠加帧抽样），算力约为主注意力的 $1/16$ 量级，但它是串行前置的——若不被隐藏，每步时延直接加上这一段的耗时。Blackwell 上的解法是把 draft 与上一帧的主注意力放在不同 stream 上异步重叠：draft 读的是当前帧 latent，主注意力写的是上一帧 KV，二者无数据依赖，WGMMA 的异步流水正好让 draft 的 MMA 填进主注意力 gather 等待 HBM 的空隙。这就是“draft 开销可隐藏”的物理基础，也是短视频场景下净收益为负时首先要检查的地方——重叠没做对，draft 就是纯加时延。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-17\">十七 · 主注意力的 gather 与流水：索引如何喂给 WGMMA</h3>\n<p>主注意力按稀疏索引 gather QKV 时，伪代码的数据流必须显式区分两档的执行路径：</p>\n<ul>\n<li>读入块级索引数组与精度标签数组，按标签把块分组，FP8 组与 FP4 组各自连续排列。</li>\n<li>FP8 组：按索引从分档 KV cache 中 gather $K_b,V_b$ 到 shared memory 的连续缓冲，发起 FlashAttention-3 风格的异步 WGMMA，softmax 在 FP32 累加器上做，输出写回 FP32 缓冲。</li>\n<li>FP4 组：gather 对应的 FP4 量化 KV，走低精度 MMA，$\\hat{A}_b$ 由 draft 分数上采样得到，同样 FP32 累加。</li>\n<li>skip 组：不发起 MMA，直接由邻帧同位置块的注意力输出做线性外推，写入输出缓冲并同步写回 KV cache 的对应槽位。</li>\n</ul>\n<p>推导上的关键一步是 gather 的代价模型。设块大小为 $p\\times p$、每块 KV 字节数为 $B_k$，若索引随机分布，每次 gather 的 HBM 事务数约为块数乘以每块跨越的 cache line 数；若预排布使同档块在物理地址上连续，则事务数降到块数本身。二者比值就是随机访存惩罚系数。把它代入带宽约束：注意力每步的 KV 读取时间 $T_{\\text{kv}}\\approx \\frac{\\sum_b B_k(b)}{BW_{\\text{eff}}}$，其中 $BW_{\\text{eff}}$ 因随机访问而低于峰值带宽。当 $T_{\\text{kv}}$ 超过 MMA 计算时间，稀疏化省下的算力就被访存吃掉——这正是失败模式“注意力时延不降反升”的定量来源。预排布块布局因此不是优化项而是正确性前提：在分档生成索引的那一步就要按档位重排 KV cache 的物理槽位，让 gather 变成按档分段的大块连续读。</p>\n<p>流水重叠的另一个细节是 FP8 与 FP4 两组的 MMA 不能互相等待：把两组分别提交到不同 stream，用事件同步而非 barrier，让 FP4 组的低精度 MMA 在 FP8 组等待 softmax 归约时插入执行。Blackwell 的 tcgen05 与 TMEM 让累加器常驻片上，两组共享同一块 FP32 累加缓冲的不同分区，避免中间结果反复落 HBM——这一步直接决定每步注意力的显存带宽占用，也是批大小受 KV cache 与稀疏索引显存双重约束的原因。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-18\">十八 · 填充与外推的误差传播：skip 块为什么不能置零</h3>\n<p>skip 块用邻帧注意力输出做线性外推，伪代码只有几行，但误差传播的分析决定了它能否写回 KV cache：</p>\n<div class=\"formula\">$$\\hat{O}_{f,b}=O_{f-1,b}+\\alpha\\,(O_{f-1,b}-O_{f-2,b})$$</div>\n<p>$\\alpha$ 是外推系数，由 draft 分数在时间维上的衰减率估计。置零会让 skip 块在后续帧的注意力中变成“空洞”——因为写回 KV cache 的 $V$ 为零，下一帧任何引用该块的查询都会得到零贡献，画面出现块状暗斑；线性外推至少保留了运动的一阶连续性，平滑区域的外推误差是二阶小量。但外推在镜头切换处失效：切换帧的 $O_{f-1}$ 与 $O_{f-2}$ 属于不同场景，差值被放大成错误的外推方向，且这个错误一旦写回 KV cache 就会污染后续所有引用该槽位的帧，形成沿时间轴扩散的污染链。</p>\n<p>工程上的抑制手段是在外推前加一道切换检测：比较相邻帧 draft 分数的整体相关性，低于阈值则对该帧所有 skip 块退化为“复制上一帧输出”而非线性外推，切断二阶项的放大；同时把外推结果标记为“低置信”，在 VAE 解码前的 BF16 残差校正阶段对这些块做更强的校正权重。代价是切换检测本身要读两帧的分数向量，是一次 $O(N_b)$ 的轻量比较，可并入 draft 的尾部。</p>\n<p>残差校正的位置也值得推敲：它放在 VAE 解码前而非注意力输出后，是因为条带伪影的成因是低精度块在空间上相邻造成的量化台阶，而 VAE 的上采样会把台阶放大成可见条纹；在 latent 域做一次 BF16 残差校正，相当于用高精度参考补上低精度块丢失的低频分量，代价是一次逐块的小规模 BF16 卷积，显存开销仅为对应块 latent 的副本。这一步的算力占比很小，但它决定了 FP4 档能否开到较高的 $\\rho_{\\text{FP4}}$——没有校正，$\\tau_2$ 必须上调，FP4 占比被迫压缩，整条公式的省算力收益随之缩水。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-19\">十九 · 公式到部署配方的映射：三个可调旋钮</h3>\n<p>把上面的推导收拢成部署时可调的三个旋钮，每个都直接对应公式里的一项：</p>\n<table class=\"mini\"><thead><tr><th>旋钮</th><th>作用对象</th><th>调节后果</th></tr></thead><tbody><tr><td>$\\tau_1$</td><td>skip 比例，即 $1-\\rho_{\\text{FP8}}-\\rho_{\\text{FP4}}$</td><td>下调则 skip 增多、FLOPs 降，但外推误差与切换污染风险升</td></tr><tr><td>$\\tau_2$</td><td>FP8 与 FP4 的分界，即 $\\rho_{\\text{FP8}}/\\rho_{\\text{FP4}}$</td><td>上调则 FP4 占比增、等效算力降，但需残差校正兜底条带</td></tr><tr><td>块粒度 $p$</td><td>gather 的连续性与索引碎度</td><td>增大则索引少、访存连续，但空间分辨率降、小块运动误判</td></tr></tbody></table>\n<p>这三个旋钮不是独立调优的：$\\tau_1$ 下调会同时抬高外推填充的占比，进而要求切换检测更灵敏；$\\tau_2$ 上调会压缩 FP8 保真项，要求残差校正权重更强；块粒度增大会让 $\\tau$ 的判定变粗，等效于把分档曲线平滑掉，可能把本该 FP8 的小块运动区误划进 FP4。部署配方上，它们由请求形态驱动——长帧序列、运动平缓占比高的视频去噪请求才值得把 $\\tau_1$ 压低；短视频或高动态场景稀疏率天然低，$\\rho_{\\text{FP8}}$ 接近 1，此时公式退化为稠密 FP8 注意力加一份白花的 draft 开销，应直接关闭稀疏路径而非硬调阈值。</p>\n<p>并行拓扑上，单卡内多头与多流流水是这条公式的默认落点：draft 与主注意力分属不同 stream，FP8 与 FP4 两组 MMA 再分属不同 stream，三级流水靠事件同步串联。跨卡扩展时，gather 的索引必须与 KV cache 的分档存储布局对齐——若 KV 按张量并行切分，每个 rank 只持有部分头的块，索引要在 rank 间广播并在本地重映射，这一步的通信量与索引碎度成正比，是规模上限的另一个约束。最终判断落在一条可操作的准则上：先测 draft 开销能否被主注意力的 HBM 等待完全隐藏，再测预排布后的 $BW_{\\text{eff}}$ 是否接近峰值，两者任一不满足，稀疏路径的净收益就为负，公式里那两项求和的加权省算力只是纸面数字。</p>\n<h3 id=\"alg-fp8-sparse-attn-video-sec-20\">二十 · 请求形态：什么样的负载才配得上这套配方</h3>\n<p>精度分配稀疏时空注意力的收益来源不是“更快的算子”，而是“更少的块被真正算”。因此它的负载前提非常硬：请求必须是长帧序列、高分辨率、去噪步数成百上千的视频生成请求，且序列内部存在大比例的平滑时空块。用工程语言表述，设一次请求的时空块总数为$B_{\\text{tot}}$，被判定为skip或FP4的块占比为$\\sigma$，则注意力侧的有效计算量近似按$(1-\\sigma)$缩放。$\\sigma$高，配方才成立；$\\sigma$低，配方只是给稠密注意力加了一层额外的索引开销。</p>\n<p>从请求形态看，它匹配的是“单条长视频、批量小、步数多”的负载：帧数长到让$O(N^2)$成为主要瓶颈，分辨率高到让KV读取成为带宽瓶颈，而去噪循环反复调用同一套注意力，使得draft开销可以在多步之间被摊薄。反过来，短片段、单图生视频、镜头切换密集的剪辑式请求，其块级重要性分数分布接近均匀，阈值$\\tau_1$切不出足够的skip块，$\\tau_2$又把大量块推入FP8档，最终退化为“稠密FP8 + 一份draft开销”，比直接跑FP8稠密注意力更慢。</p>\n<p>一个具体的判断例子：一段以静态背景、缓慢推镜为主的长镜头，draft下采样2×后得到的块级重要性图会在背景区域形成大片低分块，这些块进入skip档，主注意力只gather少量高频块；而一段手持快速摇摄、频繁遮挡的素材，draft分数在每帧每头都接近阈值附近抖动，分档结果不稳定，稀疏索引每步都在变，gather的地址序列无法复用，HBM随机读取代价上升。前者是这套配方的目标负载，后者应当直接关闭稀疏路径。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-21\">二十一 · 长度分布：阈值切分依赖分布的“双峰性”</h3>\n<p>分档规则$$\\text{tier}=\\begin{cases}\\text{skip}, &amp; s&lt;\\tau_1\\\\ \\text{FP4}, &amp; \\tau_1\\le s&lt;\\tau_2\\\\ \\text{FP8}, &amp; s\\ge\\tau_2\\end{cases}$$看起来只是两个阈值，实际上它要求重要性分数$s$的分布是双峰的：一大簇低分块和一簇高分块，中间地带薄。只有这样，$\\tau_1$与$\\tau_2$才能把块干净地分成三档，且分档在相邻去噪步之间保持稳定。若$s$的分布是单峰宽尾，任何阈值切分都会把大量块放进FP4档——这一档既要低精度MMA又要保留FP32累加，还要在VAE前做BF16残差校正，单位块的系统代价并不比FP8稠密低多少，收益却被摊薄。</p>\n<p>长度分布还通过draft开销占比影响净收益。draft注意力在2×下采样latent上做一次轻量注意力，其FLOPs约为主注意力的$1/4$量级（分辨率降2×，序列长度降4×，但注意力仍是二次的），这个开销是固定的，不随$\\sigma$变化。于是净收益的条件可以写成定性不等式：主注意力节省的算力与带宽必须大于draft开销加上gather的访存惩罚。序列越长，主注意力项按$N^2$增长，draft项按$(N/2)^2$增长，两者同阶，所以长序列本身并不自动让配方划算——真正决定划算与否的是$\\sigma$，也就是内容里平滑块的比例。</p>\n<p>工程上的做法是把长度分布当作路由信号：按帧数与分辨率估算$N$，按首步draft的分数直方图估算$\\sigma$，两者一起决定是否启用稀疏路径。首步直方图集中在低分区的请求走完整配方；直方图平坦的请求走FP8稠密档，跳过索引生成与外推填充。这个路由本身很便宜，代价只是一次draft，但它避免了在高动态请求上白付索引开销。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-22\">二十二 · 并发与批大小：被KV分档存储和索引显存卡住</h3>\n<p>这套配方的批大小不是由算力决定的，而是由两样东西决定：按精度标签分档存储的KV cache，以及每步生成的稀疏索引与精度标签。KV按标签分档意味着同一批内不同请求的KV布局不同，连续批处理时新请求加入需要重新排布块布局，否则gather会退化成随机读。索引本身也是显存：每个时空块一个索引项加一个标签，块数随$N$二次增长，批内请求一多，索引表的显存占用就与KV cache竞争同一块HBM。</p>\n<p>因此它的并发形态偏向“少请求、长序列、高步数”，而不是“多请求、短序列、高并发”。在连续批处理下，批内混合长短请求会破坏分档的稳定性：短请求的$\\sigma$低，却占着批内位置，使得整个批的gather地址序列被拉长、被打散，长请求原本可以复用的预排布块布局被稀释。工程判断是：按$\\sigma$与$N$做批内同质化，把高稀疏率的长请求聚在同一批，把低稀疏率的请求分流到稠密路径的批，而不是让调度器按到达顺序混批。</p>\n<p>具体代价可以这样看：一次主注意力的时间由三部分组成——gather后的WGMMA计算、按索引的HBM读取、以及draft与主注意力在多流上的重叠效率。批大小增大时，计算部分被摊薄，但HBM读取的地址序列变长、预排布块布局的复用率下降，第三项重叠效率也因多流竞争而下降。所以批大小存在一个由显存与访存局部性共同压出的上限，超过它，每步注意力时延不降反升，而SLO恰恰以每步注意力时延为主。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-23\">二十三 · 负载不对时：三种可观测的退化</h3>\n<p>第一种退化是稀疏率不足导致的净收益为负。短视频或高动态场景下，$\\sigma$低到主注意力节省的算力抵不过draft开销，此时每步时延比纯FP8稠密注意力更高，且高出的是一个固定的draft项。这个退化在监控上表现为：稀疏路径开启后每步注意力时延上升，而gather的HBM读取量没有明显下降。处置方式是按内容动态决定是否启用稀疏路径，而不是默认开启。</p>\n<p>第二种退化是gather破坏连续访存。稀疏索引把原本连续的QKV读取打散成按块跳读，若块布局未预排布，HBM随机读取代价抵消算力节省，注意力时延不降反升。这个退化在监控上表现为：WGMMA利用率下降而HBM读取事务数上升，算力节省被访存惩罚吃掉。处置方式是在生成索引时同步产出预排布的块布局，让同一精度档的块在物理上相邻，使gather退化为分段连续读。</p>\n<p>第三种退化是skip块外推填充在镜头切换处出错。对skip块用邻帧注意力输出做线性外推并写回KV cache，前提是邻帧内容连续；镜头切换处邻帧不连续，外推结果错误，写回KV cache后污染后续帧的注意力输出，误差沿去噪步传播。这个退化在监控上表现为：切换帧附近的输出出现结构性偏差，且VAE前的BF16残差校正只能压制条带伪影，压不住语义级错误。处置方式是在draft阶段检测帧间分数突变，把切换帧附近的块强制提升到FP8档，禁止外推。</p>\n<table class=\"mini\"><thead><tr><th>退化</th><th>触发条件</th><th>可观测信号</th><th>处置</th></tr></thead><tbody><tr><td>净收益为负</td><td>$\\sigma$低，draft开销未被重叠隐藏</td><td>每步时延上升，HBM读取未降</td><td>按内容路由，关闭稀疏路径</td></tr><tr><td>gather访存惩罚</td><td>块布局未预排布</td><td>WGMMA利用率降，读取事务数升</td><td>索引生成时同步预排布布局</td></tr><tr><td>外推错误传播</td><td>镜头切换处skip块外推</td><td>切换帧附近结构性偏差</td><td>突变帧块强制升档，禁止外推</td></tr></tbody></table>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-24\">二十四 · 配方参数与SLO的耦合</h3>\n<p>阈值$\\tau_1$、$\\tau_2$不是精度参数，是负载参数。调低$\\tau_1$会把更多块推入FP4与FP8档，稀疏率下降、时延上升但画质更稳；调高$\\tau_1$会把边缘块推入skip档，稀疏率上升、时延下降，但外推填充的比例上升，镜头切换处的错误概率上升。$\\tau_2$控制FP8稠密档的边界，它决定高频运动区域是否被完整保留——把$\\tau_2$调低会让更多块走FP8，算力代价上升，但避免了FP4档在运动区域的欠采样。</p>\n<p>由于SLO以每步注意力时延为主，配方参数应当按SLO反解：给定每步时延预算，先由draft直方图估计$\\sigma(\\tau_1,\\tau_2)$，再判断draft开销加gather惩罚是否落在预算内。若不在，说明该请求的负载形态不适合这套配方，应走稠密路径。这个反解过程本身不需要跑主注意力，代价只是一次draft与一次直方图统计，因此可以在请求准入阶段完成，而不是在去噪循环里反复试错。</p>\n<p>最后落在工程判断上：这套配方的负载配方本质是一个准入控制器——它用一次廉价的draft同时完成两件事，估计稀疏率以决定是否启用，以及生成预排布块布局以保护gather的访存局部性。把这两件事绑在同一次draft上，是这套算法在Blackwell多流上能否稳定跑在SLO内的关键；把draft只当作重要性估计而不同步产出布局，就等于把算力节省交给HBM随机读取去抵消。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-25\">二十五 · 负载配方：长帧平缓视频才是它的主场</h3>\n<p>这套方案的收益完全由内容决定，因此部署前必须把请求形态当作一等参数来配置。它面向的是长帧序列、高分辨率视频去噪：帧数越长，3D 全注意力的 O(N²) 项越占主导，跳过时空块省下的 FLOPs 与 KV 读取才够抵消 draft 开销。批大小不是自由变量，而是被 KV cache 与稀疏索引显存共同钉死的——每个块要额外存精度标签与 gather 索引，索引本身按块粒度膨胀，批一开大，索引显存先于权重显存成为瓶颈。SLO 应以每步注意力时延为主指标，而非端到端吞吐：去噪是几十步迭代的等时延链条，单步抖动会直接放大为整段视频的生成时间。</p>\n<p>分档规则本身就是一个负载敏感的超参：</p>\n<div class=\"formula\">$$\\text{tier}=\\begin{cases}\\text{skip}, &amp; s&lt;\\tau_1\\\\ \\text{FP4}, &amp; \\tau_1\\le s&lt;\\tau_2\\\\ \\text{FP8}, &amp; s\\ge\\tau_2\\end{cases}$$</div>\n<p>其中 $s$ 为 draft 块级重要性分数。$\\tau_1$ 抬高则稀疏率上升、时延下降但外推填充占比变大；$\\tau_2$ 下压则 FP8 稠密档收缩、过曝风险回升。短视频或高动态场景里，分数分布整体右移，落在 skip 档的块极少，稀疏率低到无法摊薄 draft 那次 2× 下采样注意力的固定开销，净收益为负——此时稀疏路径不是\"略微不划算\"，而是每步时延净增。工程判断是：按内容动态决定是否启用稀疏路径，把\"帧数 × 运动幅度\"作为门控信号，而不是默认开启。</p>\n<table class=\"mini\"><thead><tr><th>请求形态</th><th>稀疏率</th><th>净收益</th><th>主要代价</th></tr></thead><tbody><tr><td>长帧、运动平缓占比高</td><td>高</td><td>正，FLOPs 与 KV 读取双降</td><td>draft 开销需多流隐藏</td></tr><tr><td>短视频、高动态</td><td>低</td><td>负，每步时延增加</td><td>draft 固定开销无法摊薄</td></tr><tr><td>镜头切换密集</td><td>中</td><td>不确定</td><td>邻帧外推在切换处错误传播</td></tr></tbody></table>\n<p>负载不对时的失效是连锁的。稀疏索引 gather 破坏连续访存，若块布局未预排布，HBM 随机读取代价会抵消算力节省，注意力时延不降反升；draft 开销若未被 Blackwell 多流异步 WGMMA 重叠隐藏，短视频场景下这笔开销全额计入关键路径。更隐蔽的是正确性代价：skip 块用邻帧注意力输出线性外推填充并写回 KV cache，在镜头切换处外推假设失效，错误输出进入 cache 后污染后续帧的注意力，形成跨帧传播的伪影，BF16 残差校正只能压条带、压不住这种结构性错误。因此并发配置上应把长平缓序列与高动态序列分流到不同批次，避免同一 batch 内稀疏率被最坏样本拉低。</p>\n<h3 id=\"alg-fp8-sparse-attn-video-sec-26\">二十六 · 硬件档位与并行拓扑的绑定关系</h3>\n<p>这套算法的部署配方不是“先选卡再调参”，而是硬件档位直接决定并行拓扑的切分粒度。Blackwell 档位（SM100/SM103）上，draft 注意力与主注意力必须落在不同 CUDA stream 上，靠 WGMMA 异步流水重叠；这要求单卡内的 SM 资源被显式划分为 draft 分区与主注意力分区，而不是让两个 kernel 争抢同一批 SM。工程上的做法是：draft 走低分辨率 latent，其 tile 尺寸小、占用 SM 少，固定在少量 SM 上以低占用率常驻；主注意力按块索引 gather 后铺满剩余 SM。并行拓扑以单卡内多头 + 多流流水为主，跨卡张量并行只在单卡 KV cache 与稀疏索引显存放不下时才引入——因为 gather 索引是卡内局部结构，跨卡切头会把索引重排成本推到通信侧，NVLink 5 的带宽再宽也抵不过索引语义的碎片化。</p>\n<p>拓扑切分的判据可以用一个占用率约束表达：设 draft 分区占 $f_d$ 比例的 SM，主注意力占 $1-f_d$，则重叠有效的条件是 draft 单步耗时 $t_d$ 不超过主注意力单步耗时 $t_m$，即</p>\n<div class=\"formula\">$$f_d \\ge \\frac{t_d}{t_m}\\cdot\\frac{1}{\\eta_{\\text{occ}}}$$</div>\n<p>其中 $\\eta_{\\text{occ}}$ 是 draft kernel 的 SM 占用效率。这个式子给出的工程判断是：draft 分辨率下采样 2× 已经把 $t_d$ 压到主注意力的一个小比例，因此 $f_d$ 通常取很小的值即可；一旦实测发现 draft 未被隐藏（主注意力流上出现等待），优先调的是 draft 的 tile 粒度与 stream 优先级，而不是加 SM——加 SM 会挤压主注意力的 WGMMA 流水深度，反而拉长 $t_m$。代价侧要盯住的是每步注意力时延的方差：重叠不充分时，时延抖动比均值更能暴露问题。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-27\">二十七 · 量化方案的档位配比与累加策略</h3>\n<p>量化方案是“FP8 稠密档 + FP4 稀疏档”的混合，两档共用 FP32 累加器，这是本算法与静态 NVFP4 分块量化的根本分野：后者作用于 FFN 与投影、以权重激活统一 4bit 换 GEMM 吞吐，本算法作用于时空注意力、按内容分配精度。部署时必须把两档的 MMA 指令路径分开配置：FP8 档走 FlashAttention-3 风格的异步 WGMMA，流水深度按 K 维 tile 数展开；FP4 档走低精度 MMA 但保留 FP32 累加，累加器不能降精度，否则平滑块的过曝抑制会失效——残差校正环节依赖的正是低精度块的累加误差可被 BF16 残差补偿。</p>\n<p>档位配比由阈值 $\\tau_1,\\tau_2$ 决定，而阈值不是超参而是内容统计量：部署时按 draft 重要性分数 $s$ 的分布做分位切分，使 FP8 档覆盖高频运动块、FP4 档覆盖平滑块、skip 档覆盖近静态块。FLOPs 的账可以写成</p>\n<div class=\"formula\">$$\\text{FLOPs}\\approx \\rho_{\\text{FP8}}N^2d+\\rho_{\\text{FP4}}\\tfrac{N^2d}{2}$$</div>\n<p>其中 $\\rho_{\\text{FP8}},\\rho_{\\text{FP4}}$ 是两档实际参与的块比例。工程代价在于：FP4 档的算力节省只有一半量级（$\\tfrac{N^2d}{2}$ 项），真正的带宽节省来自 skip 档不读 KV；因此调参时应优先扩大 skip 档而非把 FP4 档往 FP8 挤——后者省不了多少算力，却直接抬高过曝风险。一个具体例子：长镜头访谈类视频，人物面部与背景大面积平滑，draft 分数分布长尾明显，分位切分后 skip 档可覆盖多数时空块，FP8 档集中在少量运动边缘块，此时每步注意力时延的下降主要来自 KV 读取量而非 MMA 吞吐。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-28\">二十八 · KV 策略：按精度标签分档存储与 gather 布局</h3>\n<p>KV 策略的核心是“按精度标签分档存储”，而不是把所有层的 KV 压成一种格式。部署上，KV cache 按块索引组织为三段连续区：FP8 区、FP4 区、skip 区（skip 块不存主 KV，只存邻帧外推所需的少量参考）。分档存储的直接收益是 gather 时按标签走不同基址，避免同一块内混精度导致的解包开销；代价是显存碎片化——三段区的容量必须按最坏情况预留，否则运行中重排会打断流水。</p>\n<p>gather 的访存代价是本算法最硬的失败模式：稀疏索引破坏连续访存，若块布局未预排布，HBM 随机读取代价会抵消算力节省，注意力时延不降反升。部署配方要求块布局在编译期或首帧预热期完成预排布，使同一精度档内的块在物理地址上连续，索引表只记录档内偏移。伪代码思路是：</p>\n<ul>\n<li>预热阶段统计 draft 分数分布，冻结 $\\tau_1,\\tau_2$ 与块到档的映射；</li>\n<li>按档重排 KV 物理布局，生成档内偏移索引表，主注意力 kernel 只读偏移表；</li>\n<li>运行期若分数漂移超阈值，触发一次重排，但重排窗口必须落在批间空隙，不得插入解码步内。</li>\n</ul>\n<p>显存侧的代价判断：分档存储本身不省显存（FP8 区仍按 FP8 存），省的是读取带宽；若显存吃紧，压缩方向应落在 skip 区的参考量上，而不是把 FP8 区降成 FP4——那会同时破坏精度分配语义与残差校正的前提。批大小受 KV cache 与稀疏索引显存双重约束，索引表的显存开销随块数线性增长，长帧序列下不可忽略。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-29\">二十九 · 调度参数：批间重排窗口与稀疏开关</h3>\n<p>调度参数里最容易被忽视的是“稀疏路径开关”的决策点位置。短视频或高动态场景稀疏率低时净收益可能为负，因此部署配方不在请求入口一刀切开启稀疏，而是在 draft 阶段先算一次全局稀疏率估计 $\\hat\\rho_{\\text{skip}}$，与阈值比较后再决定本请求走稀疏路径还是退化为纯 FP8 稠密路径。这个决策必须在预填阶段完成，不能留到解码中途切换——中途切换会触发 KV 重排，代价远超收益。</p>\n<p>批调度上，连续批处理把不同稀疏率的请求混批会拉平收益：高稀疏率请求被低稀疏率请求拖住，主注意力流的 WGMMA 流水深度按最坏块数配置。工程做法是按 $\\hat\\rho_{\\text{skip}}$ 分桶组批，桶内块数方差小，流水深度可压得更紧。调度参数还包括重排窗口的位置：重排只允许发生在批间，且需预留一段不重叠的同步点，这段同步点的时延要计入 SLO 预算。SLO 以每步注意力时延为主，因此容量规划应按“每步时延 × 步数”而非吞吐反推，稀疏率估计本身的开销要算进首步时延。</p>\n<p>一个具体例子：高动态体育片段，draft 分数分布平坦，$\\hat\\rho_{\\text{skip}}$ 低于阈值，请求退化为 FP8 稠密路径，draft 开销变成纯附加成本；此时调度层应把该请求与同类请求组批，并关闭 draft 分区的常驻占用，把 SM 全部让给主注意力。这个开关动作本身是部署配方的一部分，不是运行时自适应能兜住的。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-30\">三十 · 可复现的配置思路：从档位到参数的落地顺序</h3>\n<p>可复现的配置思路按依赖顺序推进，每一步都有明确的验收判据，避免把互相耦合的参数一起调。第一步定硬件档位与并行拓扑：单卡内多头 + 双流，draft 分区占比按前述占用率约束取小值，验收判据是主注意力流上无等待气泡。第二步定量化档位配比：按首帧预热统计冻结 $\\tau_1,\\tau_2$，验收判据是 FP8 档块比例落在预期区间且 FP4 档累加误差可被 BF16 残差校正覆盖。第三步定 KV 分档布局与索引表：完成档内物理连续预排布，验收判据是 gather 后的 HBM 读取带宽接近连续访存的理论值。第四步定调度参数：分桶组批、批间重排窗口、稀疏开关阈值，验收判据是每步注意力时延的方差收敛。</p>\n<p>这套顺序的关键在于把“稀疏索引 gather 破坏连续访存”这个失败模式前置到第三步验收，而不是等到端到端跑通才发现时延不降反升。另一个前置项是 skip 块邻帧外推在镜头切换处的错误传播：部署配方要求在 draft 阶段检测帧间分数突变，突变帧强制降级为 FP8 稠密档，不参与外推填充，避免错误写回 KV cache 后污染后续帧。稳定性技巧上，draft 用低分辨率 latent 降开销、skip 块用邻帧线性外推而非置零、VAE 前 BF16 残差校正抑制条带，这三项在配置里分别对应 draft 分辨率参数、填充策略开关、校正开关，都是可独立验收的开关项。</p>\n<p>规模上限由 draft 开销占比与稀疏率共同约束：当 $\\hat\\rho_{\\text{skip}}$ 低于使 draft 开销无法被重叠隐藏的水平，整条稀疏路径的净收益转负，此时配置应回退到纯 FP8 稠密档并把 draft 分区释放。这个回退判断写进配置而不是留给调参经验，是本配方可复现的核心——它把“高动态短视频不宜默认开启”从定性告诫变成了带阈值的工程动作。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-31\">三十一 · 三档精度配方的边界：从稀疏率与访存连续性反推部署档位</h3>\n<p>这套配方只在“长帧序列 + 运动平缓占比高”的请求形态下成立，其净收益由稀疏率与draft开销占比共同决定。设draft注意力开销为 $C_d$，主注意力相对稠密FP8的节省比例为 $\\sigma$（由skip/FP4块占比决定），则单步注意力时延近似为 $T \\approx C_d(1-\\eta) + (1-\\sigma)T_{\\text{dense}}$，其中 $\\eta$ 为draft与主注意力在多流异步WGMMA上的重叠隐藏率。当 $\\sigma &lt; C_d(1-\\eta)/T_{\\text{dense}}$ 时净收益为负——短视频、镜头频繁切换、高动态场景正是这一区间，因此部署侧必须把“是否启用稀疏路径”做成按内容判定的运行时开关，而不是默认开启。硬件档位上，该配方面向Blackwell SM100/SM103，依赖tcgen05级异步WGMMA与多流并发才能把draft藏进主注意力的流水空隙；在无法提供足够并发流或TMEM预算紧张的配置下，$\\eta$ 退化，配方自动跌回稠密FP8路径。</p>\n<p>并行拓扑以单卡内多头切分与多流流水为主，不依赖跨卡张量并行来分摊注意力——因为稀疏索引是内容相关的，跨卡切分会让gather的地址空间碎片化。批大小受两件事约束：KV cache按精度标签分档存储（FP8档与FP4档分开布局以配合gather），以及稀疏索引本身的显存占用。分档规则为</p>\n<div class=\"formula\">$$\\text{tier}=\\begin{cases}\\text{skip}, &amp; s&lt;\\tau_1\\\\ \\text{FP4}, &amp; \\tau_1\\le s&lt;\\tau_2\\\\ \\text{FP8}, &amp; s\\ge\\tau_2\\end{cases}$$</div>\n<p>阈值 $\\tau_1,\\tau_2$ 需按分辨率与帧率标定：$\\tau_1$ 过低会把平滑块误送FP4导致过曝，过高则稀疏率不足、净收益消失。量化方案是FP8稠密档与FP4稀疏档混合、两档均保留FP32累加，FP4档的低精度MMA输出必须经BF16残差校正后才进入VAE解码，否则条带伪影会在解码阶段被放大。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>系统代价</th><th>工程对策</th></tr></thead><tbody><tr><td>块布局未预排布，gather随机访存</td><td>HBM随机读取代价抵消算力节省，注意力时延不降反升</td><td>离线按帧/头重排块索引，使同档块在地址上连续</td></tr><tr><td>draft未被多流重叠隐藏</td><td>每步时延净增，短视频场景收益为负</td><td>以 $\\eta$ 为门控，低于阈值直接走稠密FP8</td></tr><tr><td>镜头切换处skip块邻帧外推</td><td>错误写回KV cache并污染后续帧注意力</td><td>切换检测触发该段强制FP8稠密重算</td></tr></tbody></table>\n<p>调度参数上，SLO以每步注意力时延为主指标，而非端到端吞吐：去噪是固定步数的迭代，单步时延抖动会直接放大为总时延方差。因此连续批处理应把长帧序列请求与短视频请求分池，前者启用稀疏路径、后者走稠密FP8，避免同一批次内稀疏率被短请求拉低而拖累整体 $\\sigma$。规模上限由draft开销占比与稀疏率共同约束——当帧数增长使 $N^2$ 项主导时配方收益上升，但当批内并发升高、KV cache分档存储的碎片化加剧时，gather的地址局部性下降，此时应降低批大小换取访存连续性，而不是继续堆并发。</p>\n<h3 id=\"alg-fp8-sparse-attn-video-sec-32\">三十二 · 显存账：三档标签把KV从连续数组变成三张表</h3>\n<p>精度分配稀疏注意力在显存上做的第一件事，是把原本一整块连续的 K/V 张量拆成按精度标签分档的三张表：FP8 稠密档、FP4 稀疏档、以及被 skip 但需要外推填充的块。分档规则本身是廉价的，$$\\text{tier}=\\begin{cases}\\text{skip}, &amp; s&lt;\\tau_1\\\\ \\text{FP4}, &amp; \\tau_1\\le s&lt;\\tau_2\\\\ \\text{FP8}, &amp; s\\ge\\tau_2\\end{cases}$$ 但它带来的显存后果并不廉价：每个时空块除了 K/V 本体，还要携带块级重要性分数 $s$、稀疏索引、精度标签，以及为 gather 预排布所需的块布局元数据。批大小因此不再只受 KV cache 字节数约束，而受“KV 字节 + 索引元数据 + 布局描述符”三者之和约束。</p>\n<p>具体机制上，KV 按精度标签分档存储意味着同一个头的 K 在不同档位下有不同的字节宽度与不同的对齐要求。FP8 档按 1 字节元素排布，FP4 档按半字节打包，两者不能共享同一条 128B 对齐的连续段，否则 gather 时会出现跨段读取。工程上可行的做法是把每个头的 KV 按块粒度切成固定大小的“块槽”，块槽内部按档位紧凑打包，块槽之间用描述符表索引。这样做的代价是显存碎片化：块槽尺寸必须按最坏情况（FP8 稠密块）预留，FP4 与 skip 块只能部分填充，实际利用率低于理论压缩比。</p>\n<p>一个具体例子：长帧序列去噪、批内多条请求共享同一套块槽池时，若某条请求的运动平缓占比高、大量块落入 skip 档，它的块槽占用远低于按 FP8 全稠密估算的额度，但池子无法把这些空槽转给另一条高动态请求，因为后者的 FP8 块需要连续大段。这就是规模上去以后显存先崩的一种形态——不是总量不够，而是档位结构不匹配导致的不可回收空洞。推理系统的直接代价是有效批大小被压低，进而每步注意力的固定开销摊薄变差。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-33\">三十三 · 带宽账：gather 把算力节省换成随机读取代价</h3>\n<p>算力侧的收益来自 $$\\text{FLOPs}\\approx \\rho_{\\text{FP8}}N^2d+\\rho_{\\text{FP4}}\\tfrac{N^2d}{2}$$，其中 $\\rho_{\\text{FP8}}$、$\\rho_{\\text{FP4}}$ 是两档实际保留的块比例。只要 $\\rho$ 之和显著小于 1，FLOPs 就下降。但注意力在 Blackwell 上从来不是纯算力问题：主注意力按稀疏索引 gather QKV，索引一旦打乱块在 HBM 中的物理顺序，原本可以整段流式读的 K/V 就退化为按块粒度的随机读取。HBM 的随机读取代价体现在行激活与突发长度利用率上——每次只取一个块槽的有效字节，却付出接近一个完整突发的传输开销。</p>\n<p>因此净收益的正确判据不是 FLOPs 比值，而是每步注意力时延里“算力项”与“带宽项”的相对变化。定性地说，当稀疏率高、块槽预排布良好、gather 命中连续段时，带宽项随 $\\rho$ 线性下降，算力项也下降，净收益为正；当稀疏率低（高动态短视频），FLOPs 只降一点，而 gather 已经把连续访存破坏掉，带宽项不降反升，净收益为负。这正是失败模式里“注意力时延不降反升”的来源。</p>\n<p>预排布块布局是把这个判据推向正侧的唯一手段：在 draft 阶段拿到块级重要性分数后，不是立即按分数排序生成索引，而是先把同一档位、同一帧邻域内的块聚成连续段，再生成索引，使 gather 的地址序列尽量单调。代价是排布本身要花一次轻量重排与描述符写入，且排布粒度越粗、连续段越长，稀疏选择的精细度就越低，$\\rho$ 的实际值会偏离理想阈值分档。工程判断是：排布粒度应按 HBM 突发长度与块槽尺寸的比值来定，而不是按重要性分数的分辨率来定。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-34\">三十四 · 通信与多流：draft 开销只能靠重叠隐藏，不能靠削减</h3>\n<p>draft 注意力是这套算法的固定税：输入 latent 下采样 2× 做一次轻量注意力，得到每帧每头的重要性分数。它的 FLOPs 远小于主注意力，但它串在关键路径上，且它读的是同一批 latent，占用同样的 HBM 带宽。Blackwell 上的处理方式是用多流异步 WGMMA 把 draft 与主注意力重叠：draft 在一条流上以低分辨率跑，主注意力在另一条流上按上一轮已生成的索引 gather 并执行 FP8/FP4 MMA，两条流的 WGMMA 指令交错发射，Tensor Core 与访存单元各自保持占用。</p>\n<p>重叠能隐藏的是 draft 的计算时间，隐藏不了的是 draft 的带宽占用与它带来的同步点。draft 必须在下一次主注意力 gather 之前完成索引生成，这个依赖构成一个每步的屏障；多流只能把这个屏障的等待窗口压到 draft 尾部的一小段，而不能消除。规模上去以后，这个屏障的代价随批大小放大：批内请求越多，draft 需要覆盖的 latent 越多，屏障窗口越长，主注意力在屏障前的空转越明显。推理系统的吞吐代价表现为每步时延中一段无法被 MMA 填充的间隙，且这段间隙不随稀疏率下降而缩小。</p>\n<p>并行拓扑上，这套算法以单卡内多头与多流流水为主，不引入跨卡通信来分摊 draft——因为 draft 的粒度是块级、帧级，跨卡切分会让索引生成需要全局同步，通信量随帧数线性增长而收益有限。真正会引入通信的是分离式预填/解码部署下 KV 按精度标签分档存储后的跨节点搬运：不同档位的 KV 字节宽度不同，NIXL 传输时若按档位分批，会退化为小消息多批次，NVLink 5 的高带宽被消息开销吃掉。可行做法是按块槽为单位整段搬运，让档位差异留在接收端的解包阶段。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-35\">三十五 · 功耗与占用：稀疏不等于省电，空转的 SM 照样耗电</h3>\n<p>稀疏跳过的块不产生 MMA 指令，但也不释放 SM。主注意力按索引 gather 时，SM 上的 warp 仍在等待地址解析与数据返回，Tensor Core 处于空闲但时钟未降。Blackwell 的功耗结构里，动态功耗主要来自 MMA 与 HBM 传输，静态与漏电占比在低占用时上升。因此“跳过大量时空块”在功耗上的收益远小于在 FLOPs 上的收益：算力项下降带来的动态功耗节省，被 gather 阶段的访存功耗与空转 SM 的静态功耗部分抵消。</p>\n<p>更细的机制是 FP4 档的低精度 MMA 保留 FP32 累加，累加器的位宽不随输入精度下降，寄存器文件与累加通路的功耗不按 4bit 缩放。这意味着 FP4 档相对 FP8 档的能效提升主要来自输入带宽减半，而非累加功耗下降。当 FP4 档占比高但块槽填充率低时，实际搬运的有效字节少、描述符与索引的搬运占比高，能效比反而变差。</p>\n<p>一个具体例子：运动平缓的长视频、稀疏率高、块槽预排布良好时，每步注意力的 HBM 传输字节显著下降，功耗随之下降；而高动态场景稀疏率低、gather 随机化严重时，虽然名义上仍走 FP8 稠密档，但地址解析与重试使有效带宽利用率下降，单位有效工作的功耗上升。工程上应把“稀疏率”与“块槽填充率”一起作为是否启用稀疏路径的判据，而不是只看 FLOPs 节省比例。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-36\">三十六 · 尾延迟：镜头切换处的外推填充是长尾来源</h3>\n<p>skip 块用邻帧注意力输出做线性外推填充并写回 KV cache，这在平稳段是廉价且正确的；在镜头切换处则是错误来源。切换帧的注意力分布与邻帧不连续，线性外推给出的是旧镜头的外推值，写回 KV cache 后污染后续帧的注意力输出。这个错误不会在当步暴露为时延，而会在后续若干步里以条带伪影或重算的形式出现——重算意味着某些块被重新拉回 FP8 稠密档，稀疏索引被改写，块槽被重新排布。</p>\n<p>尾延迟的形态因此是双重的：一是重排布与重算带来的单步时延尖峰，二是 VAE 解码前 BF16 残差校正的额外一遍读写。残差校正要对低精度块做一次 BF16 精度的补偿，读 FP4/FP8 块、写 BF16 残差，这一步的带宽开销与低精度块占比成正比，且它在解码前串行执行，无法与去噪步骤重叠。规模上去以后，尾延迟先崩的位置往往不是主注意力，而是这条“校正—解码”链路：它的时延不随批大小摊薄，反而随批内低精度块总量线性增长。</p>\n<p>工程判断是把外推填充的适用范围限制在同镜头内，用 draft 分数的帧间跳变作为切换检测信号——分数在相邻帧间突变超过阈值时，该块强制升档到 FP8 稠密而非外推。代价是切换帧附近的稀疏率下降、FLOPs 回升，但换来的是尾延迟尖峰被削平、残差校正的输入块数可控。这比在 VAE 前加大校正力度更划算，因为校正只能压伪影、不能修复被污染的 KV cache。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-37\">三十七 · 规模上去以后哪里先崩</h3>\n<p>把五条账放在一起，规模上升时先崩的顺序是可判断的。批大小上升首先撞上显存：块槽按最坏情况预留导致的空洞使有效批大小低于按字节数估算的值，这是第一道墙。跨过显存墙后，gather 的随机访存随批内块数增长而放大，带宽项先于算力项饱和，这是第二道墙——此时 FLOPs 仍在下降，但每步时延不再下降。再往上，draft 屏障窗口随批大小拉长，多流重叠的隐藏能力被耗尽，每步时延出现无法填充的间隙，这是第三道墙。</p>\n<p>尾延迟不在这个顺序里，它是独立的一条：镜头切换触发的外推错误与残差校正链路随批内低精度块总量线性增长，与批大小的关系是单调的而非饱和的，因此在任何规模上都可能成为长尾的主因。功耗则跟随带宽项与空转占用，通常在第二道墙之后才成为约束。</p>\n<p>对应的工程判断是三条：块槽池按档位分别配额而非统一最坏情况预留，用档位配额把显存墙推后；gather 的排布粒度按 HBM 突发长度定，用连续段长度换稀疏精细度，把带宽墙推后；draft 与主注意力的重叠窗口按批大小动态调整，批大时降低 draft 分辨率或减少 draft 头数，把屏障墙推后。三条都不能消除墙，只能改变撞墙的先后顺序，而顺序决定了容量规划里该给哪一项留余量。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-38\">三十八 · 稀疏率决定盈亏平衡点，而非算力峰值</h3>\n<p>这套方案的收益不是由FP8/FP4的理论峰值算力决定的，而是由实际稀疏率$\\rho_{\\text{skip}}$与draft开销占比共同决定的。把主注意力FLOPs写成可核算的形式：$$\\text{FLOPs}\\approx \\rho_{\\text{FP8}}N^2d+\\rho_{\\text{FP4}}\\tfrac{N^2d}{2}+\\underbrace{c_{\\text{draft}}\\cdot\\tfrac{N^2d}{4}}_{\\text{2×下采样}}$$，其中draft项因分辨率降为1/2而只有主注意力的四分之一量级，但它必须被多流异步WGMMA真正隐藏，否则就是纯加项。工程判断很直接：当$\\rho_{\\text{skip}}$低于某个门槛，省下的算力不足以覆盖draft与索引生成的固定成本，每步注意力时延不降反升。高动态短视频正是这种情形——块级重要性分数普遍越过$\\tau_2$，大量块落入FP8稠密档，稀疏路径退化为“带额外簿记的稠密注意力”。因此启用条件应按内容判定，而不是按模型全局默认开启。</p>\n<h3 id=\"alg-fp8-sparse-attn-video-sec-39\">三十九 · 先崩的是HBM随机访存，不是Tensor Core</h3>\n<p>规模上去以后第一个失效点几乎总是显存子系统。按索引gather QKV把原本连续的块读取打散成小粒度随机访问，Blackwell的HBM带宽再高也架不住访问粒度塌缩；若块布局未按gather顺序预排布，实际有效带宽远低于标称值，算力节省被访存代价抵消，注意力时延不降反升。第二个失效点是KV cache：按精度标签分档存储意味着同一层的KV在显存中不再是一块连续区间，FP8档与FP4档交错分布，批大小同时受KV容量与稀疏索引本身（每帧每头的块级标签与索引表）挤压，索引元数据的显存开销随帧数与头数线性增长，在长帧序列上不可忽略。第三个是尾延迟：多流流水下draft与主注意力争抢SM与访存带宽，平均吞吐好看，但单步最慢的那次往往出现在draft未及时完成、主注意力空等的时刻，SLO以每步注意力时延为主时，尾延迟比均值更早触线。</p>\n<h3 id=\"alg-fp8-sparse-attn-video-sec-40\">四十 · 精度分档的隐性代价在写回与校正</h3>\n<p>skip块用邻帧线性外推填充并写回KV cache，这一步把错误也写进了后续帧的注意力输入：镜头切换处外推失效，污染沿帧链传播，表现为解码后的闪烁而非单帧伪影。FP4档保留FP32累加缓解了累加误差，但低精度块的条带伪影要靠VAE解码前的BF16残差校正兜底，这次校正本身是一次额外的全量读写，在长帧序列上构成不可忽视的带宽与功耗开销——功耗维度上，FP4 MMA省下的能量容易被反复的残差校正与随机gather抵消。可用一张小表把失效条件与代价对齐：</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>先崩的资源</th><th>系统表现</th></tr></thead><tbody><tr><td>块布局未预排布</td><td>HBM有效带宽</td><td>时延不降反升</td></tr><tr><td>draft未被多流隐藏</td><td>SM占用与流水</td><td>每步时延净增</td></tr><tr><td>镜头切换处外推</td><td>KV cache正确性</td><td>错误跨帧传播</td></tr><tr><td>索引元数据膨胀</td><td>显存容量</td><td>批大小被迫下调</td></tr></tbody></table>\n<p>因此规模上限由三个量共同约束：draft开销占比、实际稀疏率、以及预排布后gather的访存效率。三者任一恶化，方案就从“省带宽省算力”翻转为“多花一份簿记钱”，此时正确动作是回退到FP8稠密路径，把精度分配留给真正运动平缓占比高的长帧序列。</p>\n<h3 id=\"alg-fp8-sparse-attn-video-sec-41\">四十一 · 精度分档失效：从“过曝”到“欠采样”的两种反向错误</h3>\n<p>精度分配稀疏时空注意力的核心承诺是“平滑块走FP4、高频块走FP8”，但工程上最先崩的往往不是算力，而是分档规则本身。失败模式有两种方向相反的表现：一是阈值$\\tau_1,\\tau_2$被整体压低，大量本该进FP8的高频块被误判进FP4，表现为运动边缘的拖影、快速平移物体的轮廓抖动，以及VAE解码后高频区域的“糊化”；二是阈值被整体抬高，平滑块被误判进FP8稠密档，稀疏率骤降，注意力时延不降反升，等于白付了draft开销。这两种错误都不会报错，只会以画质退化或SLO超时的形式浮现。</p>\n<p>诊断的关键是把“分档分布”当作一等指标暴露出来，而不是只看端到端时延。每个推理step记录三个量：skip块占比$\\rho_{\\text{skip}}$、FP4块占比$\\rho_{\\text{FP4}}$、FP8块占比$\\rho_{\\text{FP8}}$，以及draft分数$s$的分位数（p10/p50/p90）。正常负载下这三个占比应随内容缓慢漂移；若某一帧的$\\rho_{\\text{FP8}}$突然从稳态跳到接近1，说明draft注意力图在该帧失效——常见于镜头切换、强闪光、字幕叠加。此时应触发“分档冻结”：沿用上一帧的稀疏索引与精度标签，只对新增帧重新估计，避免单帧误判把整段序列拖进稠密路径。</p>\n<p>另一个隐蔽的精度问题是FP4档的累加。机制要求FP4档保留FP32累加，但若gather后的块布局让同一输出位置被拆到多个MMA片段，累加顺序变化会放大舍入误差，表现为低对比度平滑区域的条带。诊断方法是抽取若干skip/FP4块，用BF16参考路径重算同一块并比对相对误差；若误差在VAE残差校正前已超过可接受带，说明累加链被切碎，需要调整块排布使同一输出头的块连续累加。代价上，这类诊断本身要额外跑一条参考路径，属于离线或抽样在线，不能每步全量做，否则诊断开销会吃掉稀疏带来的算力节省。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-42\">四十二 · OOM：稀疏索引与KV分档存储的显存账</h3>\n<p>这套算法的显存压力不在权重，而在两处新增结构：稀疏索引和按精度标签分档的KV cache。索引本身是每帧每头的块级三元组（块号、档位、外推标记），批大小受KV cache与稀疏索引显存共同约束。失败模式是：批大小按KV cache估算通过，但索引在长帧序列上按$O(N_{\\text{frames}}\\times N_{\\text{heads}}\\times N_{\\text{blocks}})$增长，在连续批处理里随并发请求数线性叠加，最终在某个batch step触发OOM。由于索引是动态生成的，OOM往往发生在运行中而非启动时，表现为进程被宿主杀掉或CUDA allocator报错。</p>\n<div class=\"formula\">$$\\text{Mem}_{\\text{idx}}\\approx B\\cdot N_f\\cdot H\\cdot \\frac{N_{\\text{blk}}}{8}\\ \\text{bytes (位打包索引)}+\\text{FP8 KV}+\\text{FP4 KV}$$</div>\n<p>工程判断是：索引必须位打包并按请求生命周期分配/释放，不能挂在全局池里等GC；KV按精度标签分档存储意味着同一请求的KV被切成两段不同精度的buffer，分配器要能接受碎片化的分段，否则会出现“总量够但连续块不够”的假性OOM。诊断上监控三个量：索引显存占用量、KV分档buffer的碎片率、以及allocator的retry次数。若碎片率随step单调上升，说明分档buffer在反复扩容缩容，应改为按最大档位预分配、按标签写入。代价是预分配会抬高稳态显存占用，换取的是消除运行中OOM与分配抖动。</p>\n<p>具体例子：一个长帧高分辨率去噪请求，帧数很大、头数多，索引若按32位整型存块号，单请求索引就到数十MB量级；位打包后压到原来的几分之一，才可能把批大小从1提到2。这不是优化项，是能不能批起来的前提。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-43\">四十三 · 批抖动与路由不均：连续批处理下的稀疏率方差</h3>\n<p>连续批处理把不同内容、不同帧数的请求拼进同一step，而本算法的每步工作量正比于该step内所有请求的$\\rho_{\\text{FP8}}N^2d+\\rho_{\\text{FP4}}N^2d/2$之和。问题在于稀疏率是内容相关的：一个运动平缓的长视频请求稀疏率高、算力需求低，一个高动态短视频请求稀疏率低、几乎全走FP8。两者拼批时，step时延由最“重”的请求主导，轻请求被拖慢，形成批抖动。更糟的是调度器若按请求数而非按预估FLOPs配批，会把多个高动态请求堆进同一step，造成周期性的时延尖刺。</p>\n<p>诊断指标是每step的“有效FLOPs”与“名义FLOPs”之比，以及批内请求稀疏率的极差。若极差持续偏大，说明路由不均——要么draft估计对某类内容系统性偏低（把高频误判为平滑），要么阈值对该内容不适用。处理手段是按预估稀疏率做批内分组：把稀疏率相近的请求拼批，高动态请求单独成批并配更保守的SLO预算。代价是分组会降低批的填充率，牺牲部分吞吐换时延稳定性；在SLO以每步注意力时延为主的场景下，这个交换通常是值得的。</p>\n<p>路由不均还有一层：多头之间的分档不一致。同一帧不同注意力头可能给出差异很大的重要性分数，若按头独立分档，gather的索引在头间不连续，访存效率下降；若强行统一到帧级档位，又会牺牲精度分配的粒度。诊断时统计头间档位分歧率，分歧率高说明draft分辨率不足（下采样2×后块太粗），需要在不增加draft开销的前提下调整块划分，而不是简单调阈值。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-44\">四十四 · 尾延迟尖刺：gather访存与draft未隐藏</h3>\n<p>尾延迟尖刺有两个已列明的来源。第一是稀疏索引gather破坏连续访存：若块布局未预排布，主注意力按索引gather QKV时产生HBM随机读，随机读的带宽效率远低于连续读，单步时延被访存而非算力主导。此时算力账面上省了，实际时延不降反升。诊断方法是分别计时“gather阶段”与“MMA阶段”，若gather占比超过阈值且随稀疏率上升而恶化，就是布局问题，而非精度或调度问题。修复靠预排布块布局，使同一档位、同一输出头的块在HBM上连续，把随机读变成分段连续读。</p>\n<p>第二是draft开销未被多流重叠隐藏。机制依赖Blackwell多流异步WGMMA把draft与主注意力重叠，但重叠的前提是draft与主注意力在数据依赖上可分离、且两条流的资源不互相挤占。短视频或高动态场景稀疏率低时，主注意力本身已接近稠密，draft的相对开销占比上升，重叠窗口被压缩，draft变成串行前置，每步时延净增。诊断指标是“draft可见时延”=draft总时长−被隐藏时长；若该值随负载变重而上升，说明重叠失效。工程判断是设一个稀疏率下限：当预估$\\rho_{\\text{skip}}+\\rho_{\\text{FP4}}$低于该下限时直接走稠密FP8路径，不启用稀疏分支，避免为负收益付draft成本。</p>\n<p>尾延迟还要看尖刺的时间相关性：若尖刺与镜头切换、批内高动态请求到达同步出现，属于内容触发，应靠分档冻结与分组调度吸收；若尖刺呈周期性且与内容无关，多半是allocator或索引重建的固定开销，属于实现问题。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-45\">四十五 · 外推污染与回滚：skip块错误传播的止损</h3>\n<p>skip块用邻帧注意力输出做线性外推填充并写回KV cache，这是省算力的关键一步，也是错误传播的入口。镜头切换处，邻帧与外推帧的内容不连续，线性外推给出的是错误的外推值，写回KV cache后污染后续帧的注意力输出，且污染会沿帧链累积——因为后续帧又可能以被污染的帧为邻帧继续外推。表现为切换点之后若干帧出现鬼影或颜色漂移，且随时间加深。诊断靠“外推残差”指标：在抽样帧上用BF16重算skip块的真实注意力输出，与外推值比对；若残差在切换点附近突增，说明外推假设失效。</p>\n<p>止损机制是外推守卫：draft阶段同时估计帧间内容差异（低分辨率latent的帧间距离即可），差异超过阈值时把该帧的skip块降级为FP4实算，禁止外推；已被污染的KV条目按标签回溯失效并重算。回滚策略分两级：请求级回滚——检测到画质异常或SLO连续超时，把该请求整体切回稠密FP8路径重跑，代价是重跑算力；配置级回滚——若某类内容持续触发守卫，把该类内容的$\\tau_1$下调、关闭skip档，用精度换稳定。回滚必须带版本化的分档配置与索引格式，否则回滚后旧索引与新布局不兼容，gather会读错块。</p>\n<p>监控上建议把“外推占比”“守卫触发率”“残差超限率”与端到端时延并列看板，任一指标越界即自动降级。工程判断落在最后这一条：稀疏与精度分配是收益与风险同源的机制，稳定性不靠调参调出来，而靠把失效信号做成可观测、可自动降级、可版本化回滚的闭环——没有这个闭环，长视频负载下的一次镜头切换就足以让整批请求的输出不可用。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-46\">四十六 · 失效边界：从分档阈值到回滚判据</h3>\n<p>这套方案最脆弱的地方不在主注意力，而在分档规则本身。$\\text{tier}$ 由 draft 分数 $s$ 与两个阈值 $\\tau_1,\\tau_2$ 决定，阈值一旦按某一类素材标定，遇到镜头切换、快速摇镜或大面积遮挡时，draft 的低分辨率估计会把高频块误判为平滑块，直接落入 skip 档。此时邻帧线性外推写回的 KV cache 携带错误上下文，污染后续帧的注意力输出，表现为画面局部“拖影”或整段漂移——这类错误不会在单步时延上暴露，只能靠 VAE 解码前的 BF16 残差校正兜底，而残差校正只能压制条带伪影，压不住语义级错误传播。</p>\n<p>第二类失效是访存而非算力。稀疏索引 gather 把原本连续的 QKV 读取打散，若块布局未按索引预排布，HBM 随机读取代价会抵消算力节省，注意力时延不降反升。判断是否已越界的工程量是有效带宽利用率：当 gather 后的实际读取字节数除以理论字节数明显偏离 1，说明索引与物理布局不匹配。监控上应把每层 gather 命中率、每档块占比（skip/FP4/FP8）与每步注意力时延一起打点，三者背离即触发告警——块占比正常而时延上升，基本可判定为布局问题而非精度问题。</p>\n<div class=\"formula\">$$\\text{net}=\\rho_{\\text{FP8}}N^2d+\\rho_{\\text{FP4}}\\tfrac{N^2d}{2}+C_{\\text{draft}}+C_{\\text{gather}}-C_{\\text{skip}}$$</div>\n<p>上式是启用稀疏路径的净代价判据：draft 开销 $C_{\\text{draft}}$ 未被多流异步 WGMMA 隐藏、gather 开销 $C_{\\text{gather}}$ 超过跳过块省下的 $C_{\\text{skip}}$ 时，$\\text{net}$ 为正，方案净收益为负。短视频与高动态场景稀疏率低，正是 $\\text{net}&gt;0$ 的典型区间，因此不能默认开启稀疏路径，而应按内容在线决策。回滚策略分三级：先降精度档（FP4 块回退 FP8）以消除过曝；再关稀疏路径、恢复稠密 FP8 注意力以消除 gather 抖动；最后清空按精度标签分档存储的 KV cache 并重算，切断外推错误的传播链。批抖动与尾延迟尖刺通常源于 skip 块比例在批内不同请求间差异过大，按稀疏率对请求分桶、限制单批内稀疏率方差，比单纯调批大小更有效。</p>\n<h3 id=\"alg-fp8-sparse-attn-video-sec-47\">四十七 · 同族算法的三条分界线</h3>\n<p>把本算法放回同族里看，真正决定选型的不是“谁更先进”，而是三条分界线：<strong>作用对象</strong>（注意力 vs. FFN/投影）、<strong>精度决策的依据</strong>（静态校准 vs. 内容动态）、<strong>收益来源</strong>（GEMM吞吐/显存 vs. 注意力算力/KV带宽）。NVFP4分块量化推理与视频DiT的NVFP4分块量化推理都落在第一条线的左侧：它们把权重与激活压到4bit，收益体现在GEMM吞吐与显存占用上，对时空注意力的O(N²)结构本身不做任何削减。FP8时空注意力内核则把整条注意力链固定在FP8稠密路径上，收益是稳定的算力与带宽折半，但对平滑区域与高频区域一视同仁。本算法是唯一在注意力内部按块做“精度+稀疏”二维决策的条目，因此它的收益上限最高，同时它的收益下限也最低——稀疏率不足时，draft开销与gather代价会吃掉全部节省。</p>\n<p>第二条线决定了部署形态。静态量化类算法可以在离线阶段完成校准、权重打包与kernel选择，服务启动后每步开销恒定，容量规划可以直接用“每步GEMM时延×层数”估算。本算法每步都要跑一次draft注意力并生成稀疏索引与精度标签，其每步代价是数据相关的：</p>\n<div class=\"formula\">$$T_{\\text{step}}\\approx T_{\\text{draft}}+T_{\\text{gather}}+T_{\\text{FP8}}\\cdot\\rho_{\\text{FP8}}+T_{\\text{FP4}}\\cdot\\rho_{\\text{FP4}}+T_{\\text{fill}}$$</div>\n<p>其中$\\rho_{\\text{FP8}},\\rho_{\\text{FP4}}$为两档块占比，$T_{\\text{fill}}$是skip块外推填充的写回代价。这条式子说明：只有当$\\rho_{\\text{FP8}}+\\rho_{\\text{FP4}}$足够小、且$T_{\\text{draft}}$被多流重叠隐藏时，$T_{\\text{step}}$才会低于FP8稠密内核的固定时延。这就是为什么它不能像静态量化那样“默认开启”。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-48\">四十八 · 决策表：按场景与约束选型</h3>\n<p>下表把同族条目放在同一张表里对照，列是工程约束，行是可选算法。判断顺序建议自上而下：先看序列长度是否触发O(N²)瓶颈，再看内容是否具备可稀疏性，最后看显存与SLO哪个更紧。</p>\n<table class=\"mini\"><thead><tr><th>场景/约束</th><th>首选</th><th>次选</th><th>不适用</th></tr></thead><tbody>\n<tr><td>长帧序列、运动平缓占比高、每步注意力时延为SLO主项</td><td>精度分配稀疏时空注意力</td><td>FP8时空注意力内核（稀疏率不确定时的保守档）</td><td>NVFP4分块量化（不削减注意力复杂度）</td></tr>\n<tr><td>显存吃紧、批大小上不去、FFN与投影占主导</td><td>NVFP4分块量化推理</td><td>视频DiT的NVFP4分块量化推理</td><td>本算法（gather索引额外占显存，批反而更小）</td></tr>\n<tr><td>短视频、高动态、镜头切换频繁</td><td>FP8时空注意力内核</td><td>NVFP4分块量化</td><td>本算法（稀疏率低、外推在切换处错误传播）</td></tr>\n<tr><td>需要确定性每步时延、容量规划按最坏情况做</td><td>FP8稠密内核</td><td>静态NVFP4量化</td><td>本算法（时延数据相关，最坏情况劣于稠密）</td></tr>\n<tr><td>KV cache是主要瓶颈、需要按精度分档存储</td><td>本算法（KV按精度标签分档）</td><td>自回归视频2bit KV量化（更激进的KV压缩）</td><td>仅做权重量化的方案</td></tr>\n</tbody></table>\n<p>这张表的核心判断是：本算法与NVFP4分块量化不是替代关系而是叠加关系——前者省注意力算力与KV读取，后者省权重与激活的显存及GEMM时间，二者作用于不同算子，可以同时开启，但显存预算要同时容纳4bit权重、分档KV与稀疏索引三部分。真正互斥的是本算法与“确定性时延”诉求：只要SLO按P99而非均值考核，数据相关的$T_{\\text{step}}$就必须按高动态帧的最坏稀疏率来估。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-49\">四十九 · 与FP8稠密内核的对照：阈值怎么定</h3>\n<p>FP8时空注意力内核是本算法最直接的对照组，因为二者共享同一条FP8异步WGMMA路径，差别只在于是否引入draft、分档与skip。选型可以归结为一个阈值比较：设稠密FP8每步时延为$T_{\\text{dense}}$，则本算法的启用条件可写成</p>\n<div class=\"formula\">$$\\rho_{\\text{FP8}}+\\tfrac{1}{2}\\rho_{\\text{FP4}}&lt;\\frac{T_{\\text{dense}}-T_{\\text{draft}}-T_{\\text{gather}}-T_{\\text{fill}}}{T_{\\text{dense}}}$$</div>\n<p>右端是“扣除固定开销后仍值得省的比例”，左端是实际省下的等效算力比例（FP4按半算力计，与FLOPs公式中$\\rho_{\\text{FP4}}N^2d/2$一致）。这个不等式给出两个工程判断：其一，draft与gather的固定开销越大，要求的稀疏率越高，因此draft必须用低分辨率latent把开销压到主注意力的一个小比例，并在Blackwell多流上与主注意力重叠；其二，FP4档的边际收益只有FP8档的一半，把块从FP8降到FP4并不比直接skip更划算，阈值$\\tau_1$应偏向保守，宁可多skip也不要把中频块塞进FP4档。分档规则本身是</p>\n<div class=\"formula\">$$\\text{tier}=\\begin{cases}\\text{skip}, &amp; s&lt;\\tau_1\\\\ \\text{FP4}, &amp; \\tau_1\\le s&lt;\\tau_2\\\\ \\text{FP8}, &amp; s\\ge\\tau_2\\end{cases}$$</div>\n<p>工程上$\\tau_2$由“高频块必须保留稠密精度”这一硬约束反推：任何含快速运动或镜头切换的块，其draft分数会显著高于平滑块，$\\tau_2$应设在能把这些块全部划入FP8的位置，否则过曝与欠采样会同时出现。$\\tau_1$则由gather代价反推：skip块越多，索引越稀疏，HBM随机读取的占比越高，$\\tau_1$过低会让访存而非算力成为新瓶颈。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-50\">五十 · 与动态稀疏时空注意力的对照：精度维度是否必要</h3>\n<p>动态稀疏时空注意力只做稀疏不做精度分配，它的实现更简单：一套索引、一条FP8或BF16路径，没有精度标签，也没有VAE前的BF16残差校正。本算法多出的复杂度全部来自“同一张注意力图里同时存在两种精度”。这笔复杂度是否值得，取决于内容里平滑区域与高频区域的占比是否都不可忽略。若视频以大面积平滑背景为主、高频只占少数块，纯稀疏方案会把平滑块也压在低精度路径上，出现过曝；此时精度分配是必要的。反之，若高频块占比高到FP8档几乎覆盖全部有效块，精度标签退化为常量，本算法相对纯稀疏方案只剩draft开销这一项劣势。</p>\n<p>对照的代价项很具体：精度标签使KV cache必须按档存储，gather时同一头的QKV来自不同精度的页，破坏了原本连续的访存；而纯稀疏方案只需一套精度的KV布局，页对齐更容易做。因此在显存预算紧张、批大小受KV约束的场景里，纯稀疏方案往往能开出更大的批，吞吐反而更高。选型判断可以落在“每步注意力时延是否为SLO主项”上：是，则精度分配带来的算力节省值得付出布局复杂度；否，则简化布局换批大小更划算。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-51\">五十一 · 与KV量化、缓存复用条目的对照：瓶颈定位决定选型</h3>\n<p>自回归视频2bit KV量化把KV压到极低比特，轨迹感知缓存复用则跨去噪步复用中间结果，二者都不改变单步注意力的块结构。本算法与它们的分工由瓶颈位置决定：若profile显示单步注意力内部的HBM读取是主项，本算法的skip块直接减少读取量，且减少的是“不必算也不必读”的块，比单纯压比特更彻底；若瓶颈在跨步重复计算，缓存复用收益更大；若瓶颈在KV常驻显存导致批上不去，2bit KV量化的压缩比更直接。三者可以叠加，但叠加顺序影响收益：先做缓存复用减少步数，再做本算法的块级稀疏，最后对剩余常驻KV做低比特量化，这样每一层的收益都不会被上一层的开销抵消。</p>\n<p>一个具体的叠加例子：长镜头平缓视频，去噪步数多、帧数长。缓存复用先把相邻步的注意力输出复用掉一部分，本算法在剩余步上按draft分数跳过平滑块并把高频块锁在FP8，KV按精度标签分档后对FP4档再做低比特压缩。此时每步的HBM读取量由三部分共同决定，任一环节缺失都会让另外两环的收益打折——例如不做分档KV而直接全局2bit，FP8档的高频块会被迫在低比特下计算，过曝重新出现。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-52\">五十二 · 适用条件的硬边界与工程判断</h3>\n<p>把适用条件写成可执行的准入清单，比写成定性描述更有用。启用本算法前应同时满足：序列长度足以让O(N²)成为主项；内容经draft采样后$\\rho_{\\text{FP8}}+\\rho_{\\text{FP4}}/2$低于第三节不等式给出的门槛；块布局已在离线或首次运行时预排布，gather不产生跨页随机读；draft能与主注意力在Blackwell多流上重叠；镜头切换检测已接入，切换帧附近强制走FP8稠密并禁用skip外推，避免邻帧线性外推把错误写回KV cache污染后续帧。</p>\n<p>最后一条是硬边界而非优化项：skip块用邻帧外推填充，在镜头切换处外推的是完全无关的内容，写回KV cache后会被后续帧的注意力持续读取，错误沿时间轴传播。工程上的处理是把切换检测做成前置门控——检测到切换就把该段所有块强制划入FP8档并关闭skip，代价是这一段稀疏率归零、时延回到稠密水平，但换来的是不污染。这与第三节的阈值逻辑一致：$\\tau_1,\\tau_2$不是全局常量，而应随镜头边界动态抬升。若无法可靠检测切换，则本算法不应用于长镜头拼接类内容，退回到FP8稠密内核是更稳的工程判断。</p>\n\n<h3 id=\"alg-fp8-sparse-attn-video-sec-53\">五十三 · 选型边界：什么时候该用精度分配稀疏注意力，什么时候不该</h3>\n<p>与同族算法对照，首先要区分作用域。NVFP4 分块量化推理是静态地把权重与激活压到 4bit，收益落在 FFN 与投影 GEMM 的显存占用和吞吐上，与序列长度基本无关；而本方案是内容驱动的动态决策，收益落在时空注意力的 FLOPs 与 KV 读取上，只在长帧序列、运动平缓块占比高的视频里成立。两者不互斥：投影层用 NVFP4、注意力走 FP8/FP4 混合档，是 Blackwell 上合理的组合；但若把本方案当作通用加速开关，在高动态短视频上会直接亏本——稀疏率低时 draft 开销与 gather 开销都收不回来。另一类相邻算法是固定稀疏模式的滑窗或块稀疏注意力，它们无需 draft、索引可静态预排布、访存连续，代价是无法区分平滑与高频区域；本方案的价值恰恰在于用 draft 分数把预算挪给高频块，代价是引入了一次额外的注意力估计与不连续访存。</p>\n<p>决策可压成一张按内容特征查的表，判据是稀疏率 $\\rho_s$（skip 块占比）与 FP8 档占比 $\\rho_8$，以及 draft 开销能否被多流重叠隐藏：</p>\n<table class=\"mini\"><thead><tr><th>场景特征</th><th>推荐路径</th><th>主要代价</th></tr></thead><tbody><tr><td>长帧序列、平缓块占比高、镜头稳定</td><td>启用三档分配，skip 走邻帧外推</td><td>索引 gather 需预排布块布局</td></tr><tr><td>高动态、快速运动占比高</td><td>退回 FP8 稠密注意力</td><td>放弃稀疏收益，保时延稳定</td></tr><tr><td>短视频、帧数不足以摊薄 draft</td><td>不启用稀疏路径</td><td>draft 开销无法隐藏，净收益为负</td></tr><tr><td>镜头切换频繁</td><td>禁用 skip 档，仅保留 FP4/FP8 分档</td><td>外推填充在切换处错误传播</td></tr></tbody></table>\n<p>失效条件集中在三处。其一是访存：稀疏索引 gather 破坏连续访存，若块布局未按索引预排布，HBM 随机读取代价会抵消算力节省，注意力时延不降反升，此时应优先修布局而不是调阈值。其二是 draft 未被隐藏：draft 与主注意力未在多流上以异步 WGMMA 重叠时，短视频场景下每步时延净增。其三是 skip 外推在镜头切换处产生错误传播，写回 KV cache 后污染后续帧输出，因此切换检测应作为 skip 档的前置门控。系统代价上，批大小受 KV 分档存储与稀疏索引显存双重约束，SLO 以每步注意力时延为主，规模上限由 draft 开销占比与稀疏率共同决定。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2026 · 自回归视频服务与投机解码</td></tr><tr><td>解决什么</td><td>视频DiT的3D全注意力在长帧序列上呈O(N^2)复杂度，且统一低精度会让平滑区域过曝、高频运动区域欠采样；需要按内容…</td></tr><tr><td>一句话机制</td><td>用低分辨率latent的注意力图作为draft估计时空块重要性，对平滑块走FP4/稀疏跳过、对高频块走FP8稠密注意力…</td></tr><tr><td>代价与失效</td><td>draft注意力本身有开销，短视频/高动态场景稀疏率低时净收益可能为负。；稀疏索引gather破坏连续访存，需预排布块布局，否则HBM随机…</td></tr><tr><td>后继</td><td>流式视频生成服务化调度</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-fp8-sparse-attn-video · 共 8 个片段</p>\n";break;}}})();
